function groupAdvanceDailyCollectorsBySource(series: AdvanceDailySeries[]) {
  const grouped = new Map<string, AdvanceDailySeries[]>();
  series.forEach((item) => {
    const keys = uniqueNormalizedKeys([item.sourceId, item.label]);
    keys.forEach((key) => {
      const current = grouped.get(key) ?? [];
      current.push(item);
      grouped.set(key, current);
    });
  });
  return grouped;
}

function advanceDailyCollectorsForSurvey(row: AdvanceSurveyProgress, grouped: Map<string, AdvanceDailySeries[]>) {
  const keys = uniqueNormalizedKeys([row.sourceId, row.title, row.surveyId]);
  const seen = new Set<string>();
  const out: AdvanceDailySeries[] = [];
  keys.forEach((key) => {
    (grouped.get(key) ?? []).forEach((item) => {
      if (seen.has(item.id)) return;
      seen.add(item.id);
      out.push(item);
    });
  });
  return out;
}

function uniqueNormalizedKeys(values: unknown[]) {
  const seen = new Set<string>();
  const out: string[] = [];
  values.forEach((value) => {
    const key = normalizeMatch(value);
    if (!key || seen.has(key)) return;
    seen.add(key);
    out.push(key);
  });
  return out;
}

function buildRowBasedDailyPoints(block: MonitoreoReportBlock | null) {
  if (!block) return [];
  const columns = reportBlockColumns(block);
  const dateColumn = columns.find((column) => normalizeMatch(column) === "fecha");
  if (!dateColumn) return [];
  const out = new Map<string, AdvanceDailyPoint>();
  block.rows.forEach((row) => {
    const date = String(row[dateColumn] ?? "").trim();
    if (!date) return;
    const point = out.get(date) ?? { date, completed: 0, partial: 0, refusals: 0, refusalsPlatform: 0, refusalsPhone: 0, effective: 0, total: 0 };
    const effective = reportRowNumber(row, ["efectivas", "completas", "casos"]) ?? 0;
    const partial = reportRowNumber(row, ["parciales"]) ?? 0;
    const refusals = reportRowNumber(row, ["rechazos"]) ?? 0;
    const refusalsPlatform = reportRowNumber(row, ["rechazos plataforma"]) ?? 0;
    const refusalsPhone = reportRowNumber(row, ["rechazos telefonicos", "rechazos telefónicos"]) ?? 0;
    point.effective += effective;
    point.completed += effective;
    point.partial += partial;
    point.refusals += refusals;
    point.refusalsPlatform = (point.refusalsPlatform ?? 0) + refusalsPlatform;
    point.refusalsPhone = (point.refusalsPhone ?? 0) + refusalsPhone;
    point.total += effective + partial + refusals;
    out.set(date, point);
  });
  return Array.from(out.values()).filter((point) => point.total > 0 || point.effective > 0);
}

function advanceDailyTotals(points: AdvanceDailyPoint[]) {
  return points.reduce((totals, point) => ({
    completed: totals.completed + (point.completed || point.effective),
    partial: totals.partial + point.partial,
    refusals: totals.refusals + point.refusals,
    total: totals.total + (point.total || point.effective),
  }), { completed: 0, partial: 0, refusals: 0, total: 0 });
}

function sortAdvanceDailyPoints(points: AdvanceDailyPoint[]) {
  return [...points].sort((a, b) => {
    const aDate = parsePhoneReportDate(a.date);
    const bDate = parsePhoneReportDate(b.date);
    if (aDate && bDate) return aDate.getTime() - bDate.getTime();
    if (aDate) return -1;
    if (bDate) return 1;
    return a.date.localeCompare(b.date, "es");
  });
}

function advanceDailyPointsSignature(points: AdvanceDailyPoint[]) {
  return sortAdvanceDailyPoints(points)
    .map((point) => [
      point.date,
      point.completed || 0,
      point.effective || 0,
      point.partial || 0,
      point.refusals || 0,
      point.refusalsPlatform || 0,
      point.refusalsPhone || 0,
      point.total || 0,
    ].join(":"))
    .join("|");
}

function formatAdvanceDayLabel(value: unknown) {
  return formatPhoneDayLabel(value);
}

function formatAdvanceDayAxisLabel(value: unknown) {
  return formatPhoneDayAxisLabel(value);
}

function reportBlockColumns(block: MonitoreoReportBlock | null) {
  if (!block) return [];
  return block.columns.length ? block.columns : Array.from(new Set(block.rows.flatMap((row) => Object.keys(row))));
}

function reportBlockDateColumns(block: MonitoreoReportBlock | null) {
  return reportBlockColumns(block).filter((column) => {
    const key = normalizeMatch(column);
    return key && ![
      "unidad",
      "actor",
      "canal",
      "estado",
      "total",
      "fecha",
      "fuente",
      "source",
      "source_id",
      "source id",
      "id fuente",
      "encuesta",
      "recopilador",
      "collector",
      "collector_id",
      "collector id",
      "id recopilador",
      "tipo recopilador",
      "tipo_recopilador",
      "efectivas",
      "completas",
      "parciales",
      "rechazos",
      "rechazos plataforma",
      "rechazos telefonicos",
      "rechazos telefónicos",
      "barridos",
      "incidencias",
      "ratio incidencias",
    ].includes(key);
  });
}

function sumDailyColumn(block: MonitoreoReportBlock | null, date: string) {
  return (block?.rows ?? []).reduce((sum, row) => sum + reportNumberValue(row[date]), 0);
}

function sumDailyState(block: MonitoreoReportBlock | null, date: string, candidates: string[]) {
  const wanted = candidates.map(normalizeMatch);
  return (block?.rows ?? []).reduce((sum, row) => {
    const state = normalizeMatch(String(reportRowValue(row, ["estado"]) ?? ""));
    if (!wanted.some((candidate) => state.includes(candidate))) return sum;
    return sum + reportNumberValue(row[date]);
  }, 0);
}

function buildActorProgressCards(
  sources: MonitoreoSource[],
  config: MonitoreoConfig,
  acreditacion: MonitoreoAcreditacion,
  dashboard: MonitoreoDashboard,
): ActorProgressCard[] {
  const summaryRows = actorSummaryRowsFromReports(dashboard.acreditacion_reports ?? null);
  const actors = new Map<string, string>();
  const addActor = (actor: unknown) => {
    const label = cleanActorDimensionValue(actor);
    const key = normalizeMatch(label);
    if (label && key && !actors.has(key)) actors.set(key, label);
  };
  summaryRows.forEach((row) => addActor(row.actor));
  sources.forEach((source) => addActor(actorFromSource(source)));
  dashboard.progress.forEach((row) => addActor(row.dim_actor));
  acreditacion.componentes.forEach((comp) => addActor(comp.actor));

  return Array.from(actors.entries()).map(([key, actor]) => {
    const summary = summaryRows.find((row) => normalizeMatch(row.actor) === key) ?? null;
    const component = acreditacion.componentes.find((comp) => normalizeMatch(comp.actor) === key) ?? null;
    const mechanisms = actorMechanisms(actor, sources, dashboard.progress);
    const responseObserved = sumMechanisms(mechanisms.filter((item) => item.role !== "Universo" && item.role !== "Barrido"));
    const fallbackUniverse = firstNumber([
      summary?.universe,
      mechanisms.find((item) => item.role === "Universo")?.observed,
      component?.marco.marco_contactable,
      component?.marco.marco_actualizado,
      component?.marco.universo_bruto,
    ]);
    const universe = fallbackUniverse;
    const actorGoalMeta = goalForActor(config.goals, actor);
    const actorGoalMetaPct = goalMetaPctForActor(config.goals, actor);
    const actorGoalMetaFromPct = metaFromPercent(actorGoalMetaPct, universe);
    const meta = firstNumber([
      actorGoalMeta,
      actorGoalMetaFromPct,
      summary?.meta,
      component?.meta.n_objetivo,
      component?.marco.meta_efectiva,
    ]);
    const completedFallback = [
      component?.seguimiento.n_efectivo,
      responseObserved,
    ].map(numberOrNull).filter((value): value is number => value != null);
    const completed = summary?.completed ?? (completedFallback.length ? Math.max(...completedFallback) : null);
    const partial = summary?.partial ?? 0;
    const refusals = summary?.refusals ?? summary?.refusalsPlatform ?? 0;
    const refusalsPlatform = summary?.refusalsPlatform ?? 0;
    const refusalsPhone = summary?.refusalsPhone ?? 0;
    const respondedPlatform = summary?.respondedPlatform ?? null;
    const phoneEffective = summary?.phoneEffective ?? null;
    const phoneConciliated = summary?.phoneConciliated ?? null;
    const phoneWithoutComplete = summary?.phoneWithoutComplete ?? null;
    const unanswered = summary?.unanswered ?? (universe != null && completed != null
      ? Math.max(0, universe - completed - partial - refusals)
      : null);
    const metaPct = actorGoalMetaPct ?? safePercent(meta, universe);
    const actorProgress = safePercent(completed, meta);
    const coverageProgress = safePercent(completed, universe) ?? summary?.coverageProgress ?? null;
    const missing = meta != null && completed != null ? Math.max(0, meta - completed) : null;
    const statusTone: ActorProgressCard["statusTone"] = meta == null
      ? "muted"
      : actorProgress != null && actorProgress >= 100
        ? "complete"
        : actorProgress != null && actorProgress >= 70
          ? "steady"
          : "low";
    const status = meta == null
      ? "Meta pendiente"
      : statusTone === "complete"
        ? "Meta cubierta"
        : statusTone === "steady"
          ? "En ruta"
          : "Requiere impulso";
    return {
      id: `actor-${key}`,
      actor,
      universe,
      meta,
      metaPct,
      completed,
      partial,
      refusals,
      refusalsPlatform,
      refusalsPhone,
      respondedPlatform,
      phoneEffective,
      phoneConciliated,
      phoneWithoutComplete,
      unanswered,
      actorProgress,
      coverageProgress,
      missing,
      status,
      statusTone,
      mechanisms,
    };
  }).sort((a, b) => {
    const aNeeds = a.meta == null ? 1 : 0;
    const bNeeds = b.meta == null ? 1 : 0;
    return aNeeds - bNeeds || (b.completed ?? 0) - (a.completed ?? 0) || a.actor.localeCompare(b.actor);
  });
}

function actorSummaryRowsFromReports(reports: MonitoreoAcreditacionReports | null) {
  const resumen = reports?.sheets.find((sheet) => sheet.id === "resumen");
  const block = resumen?.blocks.find((item) => item.id === "resumen_unidad");
  return (block?.rows ?? []).map((row) => {
    const actor = cleanActorDimensionValue(reportRowValue(row, ["unidad"]));
    const completed = reportRowNumber(row, ["efectivas", "completas"]);
    const universe = reportRowNumber(row, ["universo"]);
    const coverageProgress = reportRowPercent(row, ["avance total"]);
    const advanceOrigin = normalizeMatch(reportRowValue(row, ["origen avance"]));
    const usesPhoneAdvance = advanceOrigin.includes("barrido");
    const refusalsPlatform = reportRowNumber(row, ["rechazos plataforma"]) ?? 0;
    const refusalsPhone = reportRowNumber(row, ["rechazos telefonicos", "rechazos telefónicos"]) ?? 0;
    const refusals = usesPhoneAdvance
      ? reportRowNumber(row, ["rechazos"]) ?? refusalsPhone
      : refusalsPlatform || reportRowNumber(row, ["rechazos"]) || 0;
    return {
      actor,
      universe,
      meta: reportRowNumber(row, ["minimo", "mínimo", "meta"]),
      completed,
      respondedPlatform: reportRowNumber(row, ["respondidas plataforma"]),
      partial: reportRowNumber(row, ["parciales"]) ?? 0,
      refusals,
      refusalsPlatform,
      refusalsPhone,
      unanswered: usesPhoneAdvance
        ? reportRowNumber(row, ["sin respuesta"])
        : reportRowNumber(row, ["sin respuesta plataforma", "sin respuesta"]),
      phoneEffective: reportRowNumber(row, ["efectivas telefonicas", "efectivas telefónicas"]),
      phoneConciliated: reportRowNumber(row, ["efectivas telefonicas conciliadas", "efectivas telefónicas conciliadas"]),
      phoneWithoutComplete: reportRowNumber(row, ["efectivas telefonicas sin plataforma completa", "efectivas telefónicas sin plataforma completa"]),
      coverageProgress: coverageProgress ?? safePercent(completed, universe),
    };
  }).filter((row) => row.actor);
}

function clientReportActors(report: MonitoreoClientReport): ClientReportActor[] {
  return (report.actors ?? []).map((row) => {
    const actor = String(reportRowValue(row, ["actor"]) ?? "").trim();
    const universe = reportRowNumber(row, ["universo"]) ?? 0;
    const effective = reportRowNumber(row, ["efectivas"]) ?? 0;
    const partial = reportRowNumber(row, ["parciales"]) ?? 0;
    const refusals = reportRowNumber(row, ["rechazos plataforma", "rechazos"]) ?? 0;
    const unanswered = reportRowNumber(row, ["sin respuesta plataforma", "sin respuesta"]) ?? Math.max(0, universe - effective - partial - refusals);
    const meta = reportRowNumber(row, ["meta"]);
    const gap = reportRowNumber(row, ["brecha meta", "brecha"]);
    const progress = reportRowPercent(row, ["avance universo", "avance"]);
    const metaProgress = reportRowPercent(row, ["avance meta"]);
    return {
      actor,
      universe,
      effective,
      partial,
      refusals,
      unanswered,
      progress,
      meta,
      gap,
      metaProgress,
      firstDay: String(reportRowValue(row, ["primer dia", "primer día"]) ?? "").trim(),
      lastDay: String(reportRowValue(row, ["ultima efectiva", "última efectiva"]) ?? "").trim(),
    };
  }).filter((row) => row.actor)
    .sort((a, b) => b.effective - a.effective || (b.progress ?? -1) - (a.progress ?? -1) || a.actor.localeCompare(b.actor, "es"));
}

function clientReportSources(report: MonitoreoClientReport): ClientReportSource[] {
  return (report.sources ?? []).map((row) => {
    const channel = String(reportRowValue(row, ["canal"]) ?? "").trim();
    const source = String(reportRowValue(row, ["fuente", "encuesta"]) ?? "").trim();
    const actor = clientReportSourceActor(String(reportRowValue(row, ["actor"]) ?? "").trim(), source, channel);
    return {
      actor,
      channel,
      source,
      effective: reportRowNumber(row, ["efectivas"]) ?? 0,
      partial: reportRowNumber(row, ["parciales"]) ?? 0,
      refusals: reportRowNumber(row, ["rechazos plataforma", "rechazos"]) ?? 0,
      total: reportRowNumber(row, ["total respuestas", "total"]) ?? 0,
      firstDay: String(reportRowValue(row, ["primer dia", "primer día"]) ?? "").trim(),
      lastDay: String(reportRowValue(row, ["ultima respuesta", "última respuesta", "ultima efectiva", "última efectiva"]) ?? "").trim(),
    };
  }).map((row) => ({ ...row, total: row.total || row.effective + row.partial + row.refusals }))
    .filter((row) => row.actor && row.source && row.total > 0)
    .sort((a, b) => b.total - a.total || a.actor.localeCompare(b.actor, "es") || a.source.localeCompare(b.source, "es"));
}

function clientReportSourceActor(actor: string, source: string, channel: string) {
  const direct = cleanActorDimensionValue(actor);
  if (direct) return direct;
  return inferUnitFromSourceLabel(source, channel);
}

function inferUnitFromSourceLabel(label: string, channel = "") {
  const channelKey = normalizeMatch(channel);
  const parts = label.split(/\s*[·-]\s*/).map((part) => part.trim()).filter(Boolean);
  for (const part of parts) {
    const key = normalizeMatch(part);
    if (key && key !== channelKey && !isGenericSourceUnitLabel(part)) return part;
  }
  const tail = parts.length ? parts[parts.length - 1] : label.trim();
  const tailKey = normalizeMatch(tail);
  if (tailKey && tailKey !== channelKey && !isGenericSourceUnitLabel(tail)) return tail;
  return "";
}

function isGenericSourceUnitLabel(value: unknown) {
  const key = normalizeMatch(value);
  if (!key) return true;
  if (isNonActorDimensionKey(key)) return true;
  return key === "campo"
    || key === "respuesta"
    || key === "respuestas"
    || key === "encuesta"
    || key === "encuestas"
    || key === "surveymonkey"
    || key === "google sheets"
    || key === "sheets"
    || key === "base"
    || key === "base trabajada"
    || key === "sin respuestas conectadas"
    || key.includes("barrido")
    || key.includes("fuente")
    || key.includes("campana");
}

function controlVariableRows(reports: MonitoreoAcreditacionReports | null): ControlVariableRow[] {
  const block = reportBlockForSheet(reports, "reporte", "detalle_variables_control")
    ?? reportBlockForSheet(reports, "cliente_variables_control", "variables_control");
  if (!block) return [];
  const rows = block.rows.map((row) => {
    const actor = String(reportRowValue(row, ["actor", "unidad"]) ?? "").trim();
    const variable = String(reportRowValue(row, ["variable"]) ?? "").trim();
    const value = String(reportRowValue(row, ["valor"]) ?? "").trim();
    const universe = reportRowNumber(row, ["universo"]) ?? 0;
    const effective = reportRowNumber(row, ["efectivas", "completas"]) ?? 0;
    const partial = reportRowNumber(row, ["parciales"]) ?? 0;
    const refusals = reportRowNumber(row, ["rechazos plataforma", "rechazos"]) ?? 0;
    const unanswered = reportRowNumber(row, ["sin respuesta plataforma", "sin respuesta"]) ?? Math.max(0, universe - effective - partial - refusals);
    return {
      actor,
      variable,
      value,
      universe,
      effective,
      partial,
      refusals,
      unanswered,
      baseShare: null,
      effectiveShare: null,
      deltaPp: null,
    };
  }).filter((row) => row.actor && row.variable && row.value && row.universe > 0);

  const totals = new Map<string, { universe: number; effective: number }>();
  rows.forEach((row) => {
    const key = `${normalizeMatch(row.actor)}::${normalizeMatch(row.variable)}`;
    const current = totals.get(key) ?? { universe: 0, effective: 0 };
    current.universe += row.universe;
    current.effective += row.effective;
    totals.set(key, current);
  });

  return rows.map((row) => {
    const totalsForVariable = totals.get(`${normalizeMatch(row.actor)}::${normalizeMatch(row.variable)}`);
    const baseShare = totalsForVariable && totalsForVariable.universe > 0 ? (row.universe / totalsForVariable.universe) * 100 : null;
    const effectiveShare = totalsForVariable && totalsForVariable.effective > 0 ? (row.effective / totalsForVariable.effective) * 100 : null;
    const deltaPp = baseShare != null && effectiveShare != null ? effectiveShare - baseShare : null;
    return { ...row, baseShare, effectiveShare, deltaPp };
  }).sort((a, b) => a.actor.localeCompare(b.actor, "es") || a.variable.localeCompare(b.variable, "es") || a.value.localeCompare(b.value, "es", { numeric: true }));
}

function groupControlVariableRows(rows: ControlVariableRow[]) {
  const actorMap = new Map<string, Map<string, ControlVariableRow[]>>();
  rows.forEach((row) => {
    const variables = actorMap.get(row.actor) ?? new Map<string, ControlVariableRow[]>();
    const values = variables.get(row.variable) ?? [];
    values.push(row);
    variables.set(row.variable, values);
    actorMap.set(row.actor, variables);
  });
  return Array.from(actorMap.entries()).map(([actor, variables]) => ({
    actor,
    variables: Array.from(variables.entries()).map(([variable, variableRows]) => ({
      variable,
      rows: [...variableRows].sort((a, b) => {
        const ay = Number(a.value);
        const by = Number(b.value);
        if (Number.isFinite(ay) && Number.isFinite(by)) return ay - by;
        return b.universe - a.universe || a.value.localeCompare(b.value, "es");
      }),
    })),
  }));
}

function formatSignedPp(value: number | null | undefined) {
  if (value == null || !Number.isFinite(value)) return "S/D";
  const rounded = Math.round(value);
  if (rounded === 0) return "0 pp";
  return `${rounded > 0 ? "+" : ""}${rounded} pp`;
}

function actorMechanisms(actor: string, sources: MonitoreoSource[], progress: MonitoreoRow[]): ActorMechanism[] {
  const actorKey = normalizeMatch(actor);
  const rows = progress.filter((row) => normalizeMatch(row.dim_actor) === actorKey);
  const seen = new Set<string>();
  const mechanisms: ActorMechanism[] = [];
  for (const row of rows) {
    const sourceLabel = String(row[".source_label"] ?? row.source_label ?? "").trim();
    const source = sources.find((item) => normalizeMatch(item.label) === normalizeMatch(sourceLabel))
      ?? sources.find((item) => normalizeMatch(actorFromSource(item)) === actorKey && normalizeMatch(sourceLabel).includes(normalizeMatch(item.label)));
    const role = sourceRoleForActor(source, sourceLabel);
    const rawChannel = cleanChannel(String(row.dim_canal ?? source?.dimensions?.canal ?? ""));
    const channel = source ? sourceChannelDisplay(source) : collectionChannelLabel(rawChannel);
    const modality = modalityForActorMechanism(source, rawChannel || channel, sourceLabel);
    const label = compactMechanismLabel(sourceLabel || source?.label || role);
    const id = source?.id ?? `${actorKey}-${normalizeMatch(label)}`;
    if (seen.has(id)) continue;
    seen.add(id);
    mechanisms.push({
      id,
      label,
      provider: source ? sourceProviderLabel(source.kind) : "Fuente",
      role,
      modality,
      observed: numberOrNull(row.observado),
      channel,
    });
  }
  for (const source of sources.filter((item) => normalizeMatch(actorFromSource(item)) === actorKey)) {
    if (seen.has(source.id)) continue;
    seen.add(source.id);
    mechanisms.push({
      id: source.id,
      label: compactMechanismLabel(source.label),
      provider: sourceProviderLabel(source.kind),
      role: sourceRoleForActor(source, source.label),
      modality: modalityForActorMechanism(source, source.dimensions?.canal ?? "", source.label),
      observed: null,
      channel: sourceChannelDisplay(source),
    });
  }
  return dedupeActorResponseMechanisms(mechanisms)
    .sort((a, b) => mechanismRank(a.role) - mechanismRank(b.role) || (b.observed ?? -1) - (a.observed ?? -1));
}

function dedupeActorResponseMechanisms(mechanisms: ActorMechanism[]) {
  const surveyResponsesByKey = new Map<string, ActorMechanism[]>();
  const genericObservedByKey = new Map<string, number>();
  for (const item of mechanisms) {
    if (item.role !== "Respuestas") continue;
    const key = actorResponseMechanismKey(item);
    if (!key) continue;
    if (item.provider === "SurveyMonkey") {
      const current = surveyResponsesByKey.get(key) ?? [];
      current.push(item);
      surveyResponsesByKey.set(key, current);
    } else if (item.observed != null) {
      genericObservedByKey.set(key, (genericObservedByKey.get(key) ?? 0) + item.observed);
    }
  }
  return mechanisms
    .filter((item) => (
      item.role !== "Respuestas" ||
      item.provider === "SurveyMonkey" ||
      !surveyResponsesByKey.has(actorResponseMechanismKey(item))
    ))
    .map((item) => {
      if (item.role !== "Respuestas" || item.provider !== "SurveyMonkey" || item.observed != null) return item;
      const key = actorResponseMechanismKey(item);
      const siblingCount = surveyResponsesByKey.get(key)?.length ?? 0;
      const observed = siblingCount === 1 ? genericObservedByKey.get(key) : null;
      return observed == null ? item : { ...item, observed };
    });
}

function actorResponseMechanismKey(item: ActorMechanism) {
  const channel = normalizeMatch(item.channel || modalityLabel(item.modality));
  return channel || normalizeMatch(item.label);
}

function actorProgressTotals(cards: ActorProgressCard[]) {
  const universe = cards.reduce((sum, card) => sum + (card.universe ?? 0), 0);
  const metaValues = cards.map((card) => card.meta).filter((value): value is number => value != null);
  const meta = metaValues.length ? metaValues.reduce((sum, value) => sum + value, 0) : null;
  const completed = cards.reduce((sum, card) => sum + (card.completed ?? 0), 0);
  const respondedPlatform = cards.reduce((sum, card) => sum + (card.respondedPlatform ?? 0), 0);
  const partial = cards.reduce((sum, card) => sum + (card.partial ?? 0), 0);
  const refusals = cards.reduce((sum, card) => sum + (card.refusals ?? 0), 0);
  const refusalsPlatform = cards.reduce((sum, card) => sum + (card.refusalsPlatform ?? 0), 0);
  const refusalsPhone = cards.reduce((sum, card) => sum + (card.refusalsPhone ?? 0), 0);
  const phoneEffective = cards.reduce((sum, card) => sum + (card.phoneEffective ?? 0), 0);
  const phoneConciliated = cards.reduce((sum, card) => sum + (card.phoneConciliated ?? 0), 0);
  const phoneWithoutComplete = cards.reduce((sum, card) => sum + (card.phoneWithoutComplete ?? 0), 0);
  const pending = cards.reduce((sum, card) => sum + (card.unanswered ?? 0), 0);
  const mechanisms = cards.reduce((sum, card) => sum + card.mechanisms.filter((item) => item.role !== "Universo").length, 0);
  return { universe, meta, completed, respondedPlatform, partial, refusals, refusalsPlatform, refusalsPhone, phoneEffective, phoneConciliated, phoneWithoutComplete, pending, mechanisms };
}

function formatRefusalOriginHint(totals: Pick<ReturnType<typeof actorProgressTotals>, "refusals" | "refusalsPlatform" | "refusalsPhone">) {
  const platform = Math.max(0, totals.refusalsPlatform ?? totals.refusals ?? 0);
  const phone = Math.max(0, totals.refusalsPhone ?? 0);
  const total = platform + phone;
  if (!total) return "sin rechazos";
  if (phone > 0 && platform === 0) return `${formatMetric(phone)} rechazos telefónicos`;
  if (platform > 0 && phone === 0) return `${formatMetric(platform)} rechazos plataforma`;
  if (platform || phone) {
    return `${formatMetric(total)} rechazos: ${formatMetric(platform)} plataforma · ${formatMetric(phone)} teléfono`;
  }
  return `${formatMetric(total)} rechazos`;
}

function actorGoalSummary(cards: ActorProgressCard[]) {
  const configured = cards.filter((card) => card.meta != null);
  const complete = configured.filter((card) => card.completed != null && (card.missing ?? 0) <= 0).length;
  const gaps = configured.filter((card) => (card.missing ?? 0) > 0);
  const totalGap = gaps.reduce((sum, card) => sum + (card.missing ?? 0), 0);
  const totalSurplus = configured.reduce((sum, card) => {
    if (card.completed == null || card.meta == null) return sum;
    return sum + Math.max(0, card.completed - card.meta);
  }, 0);
  const largestGap = gaps.reduce<ActorProgressCard | null>((selected, card) => {
    if (!selected) return card;
    return (card.missing ?? 0) > (selected.missing ?? 0) ? card : selected;
  }, null);
  return {
    totalActors: cards.length,
    configured: configured.length,
    complete,
    gaps: gaps.length,
    totalGap,
    totalSurplus,
    missingMeta: Math.max(0, cards.length - configured.length),
    largestGapActor: largestGap?.actor ?? "",
    largestGap: largestGap?.missing ?? 0,
  };
}

function formatActorGoalValue(summary: ReturnType<typeof actorGoalSummary>) {
  return summary.configured > 0 ? `${summary.complete}/${summary.configured}` : "S/M";
}

function formatActorGoalHint(summary: ReturnType<typeof actorGoalSummary>) {
  if (summary.configured <= 0) return "metas pendientes";
  if (summary.gaps > 0) return `${summary.gaps} con brecha · ${formatMetric(summary.totalGap)} faltan`;
  if (summary.missingMeta > 0) return `${summary.missingMeta} sin meta`;
  return "metas cubiertas";
}

function actorGoalTone(summary: ReturnType<typeof actorGoalSummary>): "base" | "target" | "ready" | "warning" {
  if (summary.configured <= 0) return "target";
  return summary.gaps > 0 ? "warning" : "ready";
}

function reportRowValue(row: MonitoreoRow, candidates: string[]) {
  const entry = Object.entries(row).find(([key]) => {
    const normalized = normalizeMatch(key);
    return candidates.some((candidate) => normalized === normalizeMatch(candidate));
  });
  return entry?.[1] ?? null;
}

function reportRowNumber(row: MonitoreoRow, candidates: string[]) {
  return numberOrNull(reportRowValue(row, candidates));
}

function reportRowPercent(row: MonitoreoRow, candidates: string[]) {
  const value = reportRowNumber(row, candidates);
  if (value == null) return null;
  return Math.abs(value) <= 1 ? value * 100 : value;
}

function reportRowRatio(row: MonitoreoRow, candidates: string[]) {
  const value = reportRowNumber(row, candidates);
  if (value == null) return null;
  return Math.abs(value) > 1 ? value / 100 : value;
}

function firstNumber(values: unknown[]) {
  for (const value of values) {
    const numeric = numberOrNull(value);
    if (numeric != null) return numeric;
  }
  return null;
}

function sumMechanisms(items: ActorMechanism[]) {
  const values = items.map((item) => item.observed).filter((value): value is number => value != null);
  return values.length ? values.reduce((sum, value) => sum + value, 0) : null;
}

function safePercent(value: number | null | undefined, total: number | null | undefined) {
  if (value == null || total == null || total <= 0) return null;
  return Math.min(100, (value / total) * 100);
}

function roundHalfUp(value: number | null | undefined) {
  if (value == null || !Number.isFinite(value)) return null;
  return Math.floor(value + 0.5);
}

function metaFromPercent(metaPct: number | null | undefined, universe: number | null | undefined) {
  if (metaPct == null || universe == null || universe <= 0) return null;
  return roundHalfUp((universe * metaPct) / 100);
}

function formatPercentLabel(value: number | null | undefined) {
  return value == null ? "S/M" : `${Math.round(value)}%`;
}

function actorMetaPercent(card: Pick<ActorProgressCard, "meta" | "metaPct" | "universe">) {
  return card.metaPct ?? safePercent(card.meta, card.universe);
}

function formatActorMetaPercentLabel(card: Pick<ActorProgressCard, "meta" | "metaPct" | "universe">) {
  return formatPercentLabel(actorMetaPercent(card));
}

function formatActorMetaValueLabel(card: Pick<ActorProgressCard, "meta">) {
  return card.meta == null ? "S/M" : formatMetric(card.meta);
}

function formatActorMetaContext(card: Pick<ActorProgressCard, "meta">) {
  return card.meta == null ? "sin meta" : `${formatMetric(card.meta)} casos`;
}

function actorFromSource(source: MonitoreoSource) {
  return cleanActorDimensionValue(source.dimensions?.carrera)
    || cleanActorDimensionValue(source.dimensions?.segmento)
    || cleanActorDimensionValue(source.dimensions?.actor)
    || "";
}

function cleanActorDimensionValue(value: unknown) {
  const label = String(value ?? "").trim();
  const key = normalizeMatch(label);
  if (!label || isNonActorDimensionKey(key)) return "";
  return label;
}

function isNonActorDimensionKey(key: string) {
  if (!key) return true;
  if (["sin dato", "sin actor", "sin asignar", "na", "n/a", "none", "null"].includes(key)) return true;
  return isOperationalChannelKey(key);
}

function isOperationalChannelKey(key: string) {
  if (!key) return false;
  return [
    "web",
    "online",
    "digital",
    "telefonico",
    "telefono",
    "teléfono",
    "correo",
    "email",
    "mail",
    "whatsapp",
    "sms",
    "qr",
    "ficha qr",
    "presencial",
    "personalizado",
  ].includes(key);
}

function isUnitGoalFilterKey(key: string) {
  const normalized = normalizeMatch(key);
  return normalized.includes("actor") || normalized.includes("carrera") || normalized.includes("segment");
}

function goalForActor(goals: MonitoreoGoal[], actor: string) {
  const actorKey = normalizeMatch(actor);
  const goal = goals.find((item) => Object.entries(item.filters).some(([key, value]) => (
    isUnitGoalFilterKey(key) && normalizeMatch(value) === actorKey
  )));
  return goal?.meta ?? null;
}

function goalMetaPctForActor(goals: MonitoreoGoal[], actor: string) {
  const actorKey = normalizeMatch(actor);
  const goal = goals.find((item) => Object.entries(item.filters).some(([key, value]) => (
    isUnitGoalFilterKey(key) && normalizeMatch(value) === actorKey
  )));
  return numberOrNull(goal?.meta_pct);
}

function upsertGoalForActor(goals: MonitoreoGoal[], actor: string, meta: number | null, metaPct: number | null = null, filterKey = "actor") {
  const actorKey = normalizeMatch(actor);
  const index = goals.findIndex((item) => Object.entries(item.filters).some(([key, value]) => (
    isUnitGoalFilterKey(key) && normalizeMatch(value) === actorKey
  )));
  if (meta == null) {
    return index >= 0 ? goals.filter((_, i) => i !== index) : goals;
  }
  const nextGoal: MonitoreoGoal = { filters: { [filterKey]: actor }, meta };
  if (metaPct != null) nextGoal.meta_pct = metaPct;
  if (index >= 0) return goals.map((goal, i) => i === index ? nextGoal : goal);
  return [...goals, nextGoal];
}

function sourceRoleForActor(source: MonitoreoSource | undefined, fallback: string) {
  const role = source?.role ?? "";
  if (role === "universo") return "Universo";
  if (role === "barrido") return "Barrido";
  if (role === "respuestas") return "Respuestas";
  const normalized = normalizeMatch(fallback);
  if (normalized.includes("universo")) return "Universo";
  if (normalized.includes("barrido") || normalized.includes("telefon")) return "Barrido";
  return "Respuestas";
}

function modalityForActorMechanism(source: MonitoreoSource | undefined, channel: string, label: string): MonitoreoStrategyPhase["modality"] {
  const normalized = normalizeMatch(`${channel} ${label}`);
  if (normalized.includes("telefon")) return "telefono";
  if (normalized.includes("whatsapp")) return "whatsapp";
  if (normalized.includes("sms")) return "sms";
  if (normalized.includes("presencial") || normalized.includes("qr")) return "presencial";
  if (source?.kind === "google_sheets" && source.role === "universo") return "mixto";
  return "email";
}

function cleanChannel(value: string) {
  const raw = String(value ?? "").trim();
  return normalizeMatch(raw) === "sin dato" ? "" : raw;
}

type CollectionChannelKey = "correo" | "telefono" | "presencial" | "whatsapp" | "sms" | "mixto";

function collectionChannelKey(value: string): CollectionChannelKey {
  const normalized = normalizeMatch(value);
  if (normalized.includes("telefon")) return "telefono";
  if (normalized.includes("whatsapp")) return "whatsapp";
  if (normalized.includes("sms")) return "sms";
  if (normalized.includes("presencial") || normalized.includes("qr")) return "presencial";
  if (normalized.includes("correo") || normalized.includes("email") || normalized.includes("mail")) return "correo";
  if (normalized.includes("web") || normalized.includes("online") || normalized.includes("link")) return "correo";
  return "mixto";
}

function collectionChannelLabel(value: string) {
  const key = collectionChannelKey(value);
  if (key === "correo") return "Correo";
  if (key === "telefono") return "Telefónico";
  if (key === "presencial") return "Ficha QR";
  if (key === "whatsapp") return "WhatsApp";
  if (key === "sms") return "SMS";
  return prettyOperationalLabel(cleanChannel(value) || "Mixto");
}

function collectionChannelOptionIdentity(value: string) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const key = collectionChannelKey(raw);
  return key === "mixto" ? `mixto:${normalizeMatch(raw)}` : key;
}

function uniqueCollectionChannelOptions(values: string[]) {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    const option = String(value ?? "").trim();
    const identity = collectionChannelOptionIdentity(option);
    if (!option || !identity || seen.has(identity)) continue;
    seen.add(identity);
    out.push(option);
  }
  return out;
}

function collectionChannelSelectValue(value: string, options: string[]) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const normalized = normalizeMatch(raw);
  const exact = options.find((option) => normalizeMatch(option) === normalized);
  if (exact) return exact;
  const identity = collectionChannelOptionIdentity(raw);
  return options.find((option) => collectionChannelOptionIdentity(option) === identity) ?? raw;
}

function collectionChannelIcon(value: string) {
  const key = collectionChannelKey(value);
  if (key === "correo") return Mail;
  if (key === "telefono") return PhoneCall;
  if (key === "presencial") return QrCode;
  if (key === "whatsapp" || key === "sms") return ContactRound;
  return Route;
}

function CollectionChannelBadge({ channel, compact = false }: { channel: string; compact?: boolean }) {
  const key = collectionChannelKey(channel);
  const Icon = collectionChannelIcon(channel);
  return (
    <span className={`mon-channel-badge is-${key}${compact ? " is-compact" : ""}`}>
      <Icon size={12} />
      {collectionChannelLabel(channel)}
    </span>
  );
}

function CollectionChannelSelect({
  label,
  value,
  options,
  disabled,
  onChange,
}: {
  label: string;
  value: string;
  options: string[];
  disabled?: boolean;
  onChange: (value: string) => void;
}) {
  const selectOptions = uniqueCollectionChannelOptions([...options, value]);
  const selectValue = collectionChannelSelectValue(value, selectOptions);
  const displayValue = value || selectValue;
  const Icon = collectionChannelIcon(displayValue);
  const key = collectionChannelKey(displayValue);
  return (
    <label className="mon-channel-select">
      <span>{label}</span>
      <div className={`mon-channel-select-control is-${key}`}>
        <Icon size={14} />
        <select value={selectValue} disabled={disabled} onChange={(e) => onChange(e.target.value)}>
          {selectOptions.map((option) => (
            <option key={option} value={option}>{collectionChannelLabel(option)}</option>
          ))}
        </select>
      </div>
    </label>
  );
}

function surveyChannelSummary(sources: MonitoreoSource[]) {
  const counts = new Map<CollectionChannelKey, { channel: string; count: number }>();
  for (const source of sources) {
    const channel = sourceChannelDisplay(source);
    const key = collectionChannelKey(channel);
    const current = counts.get(key);
    if (current) current.count += 1;
    else counts.set(key, { channel, count: 1 });
  }
  const rank: CollectionChannelKey[] = ["correo", "telefono", "whatsapp", "presencial", "sms", "mixto"];
  return Array.from(counts.entries())
    .map(([key, value]) => ({ key, ...value }))
    .sort((a, b) => rank.indexOf(a.key) - rank.indexOf(b.key));
}

function compactMechanismLabel(label: string) {
  return label
    .replace(/^SurveyMonkey\s*·\s*/i, "")
    .replace(/^Universo\s*·\s*/i, "Base · ")
    .replace(/^Barrido telef[oó]nico\s*·\s*/i, "Barrido · ")
    .replace(/^Correo completos\s*·\s*/i, "Correo · ")
    .replace(/\s·\sWeb\b/gi, " · Correo");
}

function mechanismRank(role: string) {
  if (role === "Universo") return 0;
  if (role === "Barrido") return 1;
  return 2;
}

function StrataDashboardCardView({ card }: { card: StrataDashboardCard }) {
  const Icon = modalityIcon(card.modality);
  const actualLabel = actualLabelForModality(card.modality);
  const barWidth = card.percent == null ? 0 : Math.max(3, Math.min(100, card.percent));
  const dialDegrees = card.percent == null ? 0 : Math.max(0, Math.min(100, card.percent)) * 3.6;
  const missingLabel = card.missing == null ? "S/D" : formatMetric(card.missing);
  const ratioLabel = card.meta == null
    ? `${formatMetric(card.observed)} logradas`
    : `${formatMetric(card.observed)} / ${formatMetric(card.meta)}`;
  const context = stratumContextChips(card.detail);
  const status = card.percent == null ? "Sin meta" : card.percent >= 100 ? "Meta cubierta" : card.percent >= 70 ? "En ruta" : "Requiere impulso";
  const statusTone = card.percent == null ? "muted" : card.percent >= 100 ? "complete" : card.percent >= 70 ? "steady" : "low";
  return (
    <article className={`mon-strata-card is-${card.modality}`}>
      <header className="mon-strata-card-head">
        <div>
          <span className="mon-op-channel"><Icon size={13} /> {modalityLabel(card.modality)}</span>
          <strong>{card.title}</strong>
        </div>
      </header>
      <div className="mon-strata-visual">
        <div className="mon-strata-dial-stack">
          <div
            className={`mon-strata-dial is-${statusTone}`}
            style={{ "--dial": `${dialDegrees}deg` } as CSSProperties}
          >
            <div>
              <strong>{card.percentLabel}</strong>
            </div>
          </div>
          <span className={`mon-strata-status is-${statusTone}`}>{status}</span>
        </div>
        <div className="mon-strata-score">
          <div className="mon-strata-metrics">
            <VisualMetric label={actualLabel} value={formatMetric(card.observed)} tone={card.observed == null ? "missing" : "ready"} />
            <VisualMetric label="Meta" value={formatMetric(card.meta)} tone={card.meta == null ? "missing" : "ready"} />
            <VisualMetric label="Faltan" value={missingLabel} tone={card.missing == null ? "missing" : card.missing > 0 ? "warning" : "ready"} />
            <VisualMetric label="Alertas" value={formatMetric(card.alerts)} tone={card.alerts > 0 ? "warning" : "ready"} />
          </div>
          <div className="mon-strata-chart" aria-label={card.meta == null ? "Participación de respuestas válidas" : "Avance sobre meta"}>
            <div className="mon-strata-chart-track">
              <span style={{ width: `${barWidth}%` }} />
            </div>
            <p>
              <span>{ratioLabel}</span>
              <strong>{card.percentLabel}</strong>
            </p>
          </div>
        </div>
      </div>
      <footer className="mon-strata-context">
        <div>
          {context.map((item) => <span key={item}>{item}</span>)}
        </div>
        <em>{card.support}</em>
      </footer>
    </article>
  );
}

function VisualMetric({
  label,
  value,
  tone,
}: {
  label: string;
  value: string;
  tone: "ready" | "warning" | "missing";
}) {
  return (
    <div className={`mon-visual-metric is-${tone}`}>
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}

function buildStrataDashboardCards(
  sources: MonitoreoSource[],
  config: MonitoreoConfig,
  acreditacion: MonitoreoAcreditacion,
  dashboard: MonitoreoDashboard,
): StrataDashboardCard[] {
  const strata = buildOperationalStrata(sources, config, acreditacion);
  const totalValid = numberOrFallback(dashboard.kpis.valid, 0);
  return strata.map((stratum) => {
    const phase = phaseForStratum(stratum.title, config.strategy_phases);
    const source = sourceForPhase(phase ?? phaseLikeFromStratum(stratum), sources);
    const row = phase
      ? progressRowForPhase(phase, source, dashboard.progress)
      : progressRowForStratum(stratum, source, dashboard.progress);
    const observed = numberOrNull(row?.observado);
    const meta = numberOrNull(row?.meta) ?? stratum.meta;
    const missingRaw = numberOrNull(row?.faltante);
    const missing = missingRaw ?? (meta == null || observed == null ? null : Math.max(0, meta - observed));
    const percent = meta != null && observed != null && meta > 0
      ? Math.min(100, (observed / meta) * 100)
      : observed != null && totalValid > 0
        ? Math.min(100, (observed / totalValid) * 100)
        : null;
    const observedUse = observedCollectorUseForStratum(stratum, config.operational_model.link_collectors);
    const observedModality = modalityFromObservedUse(stratum, observedUse);
    const modality = phase?.modality ?? observedModality ?? inferModalityForStratum(stratum.title);
    return {
      id: stratum.id,
      title: stratum.title,
      detail: stratum.detail,
      modality,
      observed,
      meta,
      missing,
      percent,
      percentLabel: percent == null ? "S/D" : `${percent.toFixed(0)}%`,
      alerts: countAlertsForStratum(dashboard.inconsistencies, stratum, source),
      support: supportLabelForModality(modality, config),
    };
  });
}

function phaseForStratum(title: string, phases: MonitoreoStrategyPhase[]) {
  const normalized = normalizeMatch(title);
  return phases.find((phase) => {
    const phaseTitle = normalizeMatch(phase.stratum);
    return phaseTitle && (phaseTitle === normalized || phaseTitle.includes(normalized) || normalized.includes(phaseTitle));
  }) ?? null;
}

function phaseMatchesStratum(phase: MonitoreoStrategyPhase, title: string) {
  const normalized = normalizeMatch(title);
  const phaseTitle = normalizeMatch(phase.stratum);
  return Boolean(phaseTitle && normalized && (
    phaseTitle === normalized ||
    phaseTitle.includes(normalized) ||
    normalized.includes(phaseTitle)
  ));
}

function phaseEntriesForStratum(title: string, phases: MonitoreoStrategyPhase[]) {
  return phases
    .map((phase, index) => ({ phase, index }))
    .filter((entry) => phaseMatchesStratum(entry.phase, title))
    .sort((a, b) => {
      const aWeek = a.phase.start_week ?? Number.MAX_SAFE_INTEGER - a.index;
      const bWeek = b.phase.start_week ?? Number.MAX_SAFE_INTEGER - b.index;
      return aWeek - bWeek || a.index - b.index;
    });
}

function defaultPhaseForStratum(
  stratum: OperationalStratum,
  modality: MonitoreoStrategyPhase["modality"],
  patch: Partial<MonitoreoStrategyPhase> = {},
): MonitoreoStrategyPhase {
  return {
    ...DEFAULT_STRATEGY_PHASE,
    id: `fase-${stratum.id}-${Date.now()}-${Math.round(Math.random() * 1000)}`,
    stratum: stratum.title,
    modality,
    start_week: patch.start_week ?? 1,
    end_week: patch.end_week ?? null,
    target_rule: DEFAULT_SCOPE_BY_MODALITY[modality],
    kpi_focus: KPI_FOCUS_OPTIONS_BY_MODALITY[modality].slice(0, 3),
    kpi_modules: DEFAULT_KPI_MODULES_BY_MODALITY[modality],
    ...patch,
  };
}

function phaseWithModality(
  phase: MonitoreoStrategyPhase,
  stratum: OperationalStratum,
  modality: MonitoreoStrategyPhase["modality"],
) {
  return {
    ...phase,
    stratum: phase.stratum || stratum.title,
    modality,
    target_rule: DEFAULT_SCOPE_BY_MODALITY[modality],
    kpi_focus: KPI_FOCUS_OPTIONS_BY_MODALITY[modality].slice(0, 3),
    kpi_modules: DEFAULT_KPI_MODULES_BY_MODALITY[modality],
  };
}

function observedCollectorUseForStratum(stratum: OperationalStratum, collectors: MonitoreoLinkCollector[]) {
  const sourceId = stratum.source_id;
  const title = normalizeMatch(stratum.title);
  const matches = collectors.filter((collector) => (
    (sourceId && collector.source_id === sourceId) ||
    normalizeMatch(collector.source_label) === title ||
    normalizeMatch(collector.source_label).includes(title) ||
    title.includes(normalizeMatch(collector.source_label))
  ));
  const use = matches.find((collector) => collector.operational_use !== "sin_clasificar")?.operational_use
    ?? matches[0]?.operational_use
    ?? "";
  if (!use) return null;
  return COLLECTOR_USE_OPTIONS.find((option) => option.value === use) ?? null;
}

function modalityFromObservedUse(stratum: OperationalStratum, observed: { value: MonitoreoCollectorUse; modality: MonitoreoStrategyPhase["modality"] } | null) {
  if (!observed) return null;
  if (observed.value === "enlace_abierto" && /estudiant|alumn/i.test(normalizeMatch(stratum.title))) {
    return "presencial";
  }
  return observed.modality;
}

function phaseLikeFromStratum(stratum: OperationalStratum): MonitoreoStrategyPhase {
  return {
    id: stratum.id,
    stratum: stratum.title,
    modality: inferModalityForStratum(stratum.title),
    start_week: null,
    end_week: null,
    target_rule: "",
    kpi_focus: [],
    kpi_modules: [],
    breakdown_vars: [],
    attempts_var: "",
    outcome_var: "",
  };
}

function progressRowForStratum(
  stratum: OperationalStratum,
  source: MonitoreoSource | null,
  rows: MonitoreoRow[],
) {
  const candidates = [
    stratum.title,
    stratum.detail,
    source?.label,
    ...sourceDimensionEntries(source?.dimensions).map(([, value]) => value),
  ].map(normalizeMatch).filter(Boolean);
  return rows.find((row) => Object.values(row).some((value) => {
    const normalized = normalizeMatch(value);
    return normalized && candidates.some((candidate) => candidate === normalized || candidate.includes(normalized) || normalized.includes(candidate));
  })) ?? null;
}

function countAlertsForStratum(
  rows: MonitoreoRow[],
  stratum: OperationalStratum,
  source: MonitoreoSource | null,
) {
  const candidates = [
    stratum.title,
    source?.label,
    ...sourceDimensionEntries(source?.dimensions).map(([, value]) => value),
  ].map(normalizeMatch).filter(Boolean);
  return rows.filter((row) => Object.values(row).some((value) => {
    const normalized = normalizeMatch(value);
    return normalized && candidates.some((candidate) => candidate === normalized || candidate.includes(normalized) || normalized.includes(candidate));
  })).length;
}

function actualLabelForModality(value: MonitoreoStrategyPhase["modality"] | string) {
  if (value === "presencial") return "QR válidos";
  if (value === "telefono") return "Efectivas";
  return "Respondidas";
}

function supportLabelForModality(value: MonitoreoStrategyPhase["modality"], config: MonitoreoConfig) {
  if (value === "telefono") {
    return config.enumerator_var ? `Equipo: ${config.enumerator_var}` : "Barrido pendiente";
  }
  if (value === "presencial") {
    return "QR presencial";
  }
  if (value === "email") {
    return "Respuesta de plataforma";
  }
  return modalityDataSupportLabel(value);
}

function inferModalityForStratum(title: string): MonitoreoStrategyPhase["modality"] {
  const normalized = normalizeMatch(title);
  if (normalized.includes("egres")) return "telefono";
  if (normalized.includes("estudiant") || normalized.includes("alumn")) return "presencial";
  return "email";
}

function formatMetric(value: number | null) {
  return value == null ? "S/D" : value.toLocaleString("es-PE");
}

function stratumContextChips(detail: string) {
  const parts = detail
    .split(";")
    .map((item) => item.trim().replace(/\.$/, ""))
    .filter(Boolean);
  const compact = parts.map((item) => {
    const normalized = item
      .replace(/^Universo/i, "Universo")
      .replace(/^meta minima/i, "Meta min.")
      .replace(/^recomendada/i, "Recom.")
      .replace(/^tecnica/i, "Tecnica:")
      .replace(/^control/i, "Control:");
    return normalized.length > 34 ? `${normalized.slice(0, 31)}...` : normalized;
  });
  return compact.slice(0, 4);
}

function OperationalFollowupPanel({
  sources,
  config,
  dashboard,
  nRows,
}: {
  sources: MonitoreoSource[];
  config: MonitoreoConfig;
  dashboard: MonitoreoDashboard | null;
  nRows: number;
}) {
  const activeSources = sources.filter((source) => source.enabled);
  const targets = [
    ...config.goals.map((goal, index) => ({ id: `goal-${index}`, meta: goal.meta })),
    ...config.operational_model.targets.map((target) => ({ id: target.id, meta: target.meta })),
  ].filter((target) => Number.isFinite(target.meta) && Number(target.meta) > 0);
  const valid = numberOrFallback(dashboard?.kpis.valid, 0);
  const total = dashboard ? numberOrFallback(dashboard.kpis.total, nRows) : nRows;
  const hasEnumerator = Boolean(config.enumerator_var);
  const kpiBlocks = buildOperationalKpiBlocks(config, sources, dashboard);

  return (
    <div className="mon-operational-followup">
      <Panel
        className="mon-fill-panel mon-followup-panel"
        eyebrow="Seguimiento operativo"
        title={<span className="mon-title-icon"><Route size={16} /> Avance por modelo local</span>}
      >
        <div className="mon-followup-overview">
          <div className="mon-followup-card">
            <span>Fuentes</span>
            <strong>{activeSources.length}/{sources.length}</strong>
            <em>{activeSources.map((source) => source.label).slice(0, 2).join(" · ") || "Sin fuente activa"}</em>
          </div>
          <div className="mon-followup-card">
            <span>Respuestas</span>
            <strong>{valid}/{total}</strong>
            <em>{dashboard ? "Válidas sobre sincronizadas" : "Sin sincronizar"}</em>
          </div>
          <div className="mon-followup-card">
            <span>Metas</span>
            <strong>{targets.length || "S/D"}</strong>
            <em>{targets.length ? "Metas configuradas" : "Pendiente definir cuotas"}</em>
          </div>
          <div className="mon-followup-card">
            <span>Equipo</span>
            <strong>{hasEnumerator ? config.enumerator_var : "S/D"}</strong>
            <em>{hasEnumerator ? "Variable asignada" : "Requiere barrido o responsable"}</em>
          </div>
        </div>
      </Panel>

      <div className="mon-stage-table-grid">
        <TablePanel title="Cortes sincronizados" icon={<Target size={16} />} rows={dashboard?.progress ?? []} />
        <OperationalKpiPanel blocks={kpiBlocks} />
      </div>
    </div>
  );
}

type OperationalKpiStatus = "ready" | "warning" | "missing";

type OperationalKpiItem = {
  label: string;
  value: string;
  hint: string;
  status: OperationalKpiStatus;
};

type OperationalKpiBlock = {
  id: string;
  title: string;
  detail: string;
  modality: MonitoreoStrategyPhase["modality"];
  items: OperationalKpiItem[];
};

function OperationalKpiPanel({ blocks }: { blocks: OperationalKpiBlock[] }) {
  return (
    <Panel
      className="mon-fill-panel mon-operational-kpi-panel"
      eyebrow="Seguimiento"
      title={<span className="mon-title-icon"><ListChecks size={16} /> Indicadores por modalidad</span>}
    >
      <div className="mon-op-kpi-grid">
        {blocks.length ? blocks.map((block) => (
          <OperationalKpiBlockCard key={block.id} block={block} />
        )) : (
          <EmptyState
            icon={<Route size={18} />}
            title="Sin mecanismos configurados"
            hint="Define cómo se recoge información por cada corte para activar indicadores."
            variant="inline"
          />
        )}
      </div>
    </Panel>
  );
}

function OperationalKpiBlockCard({ block }: { block: OperationalKpiBlock }) {
  const Icon = modalityIcon(block.modality);
  return (
    <article className={`mon-op-kpi-block is-${block.modality}`}>
      <header className="mon-op-kpi-head">
        <div>
          <span className="mon-op-channel"><Icon size={13} /> {modalityLabel(block.modality)}</span>
          <strong>{block.title}</strong>
          <em>{block.detail}</em>
        </div>
      </header>
      <div className="mon-op-kpi-metrics">
        {block.items.map((item) => (
          <div key={item.label} className={`mon-op-metric is-${item.status}`}>
            <span>{item.label}</span>
            <strong>{item.value}</strong>
            <em>{item.hint}</em>
          </div>
        ))}
      </div>
    </article>
  );
}

function buildOperationalKpiBlocks(
  config: MonitoreoConfig,
  sources: MonitoreoSource[],
  dashboard: MonitoreoDashboard | null,
): OperationalKpiBlock[] {
  return config.strategy_phases.map((phase, index) => {
    const source = sourceForPhase(phase, sources);
    const row = progressRowForPhase(phase, source, dashboard?.progress ?? []);
    const observed = numberOrNull(row?.observado);
    const configuredMeta = source ? goalForDimensions(config.goals, source.dimensions) : null;
    const meta = numberOrNull(row?.meta) ?? configuredMeta;
    const missingRaw = numberOrNull(row?.faltante);
    const missing = missingRaw ?? (meta == null || observed == null ? null : Math.max(0, meta - observed));
    const completePct = meta == null || observed == null || meta <= 0 ? null : Math.min(100, (observed / meta) * 100);
    const roster = config.operational_model.cases.roster_source;
    const hasEnumerator = Boolean(config.enumerator_var);
    const hasOperationalRoster = roster === "external_local" || roster === "uploaded";
    const validValue = observed == null ? "S/D" : observed.toLocaleString("es-PE");
    const metaValue = meta == null ? "S/D" : meta.toLocaleString("es-PE");
    const missingValue = missing == null ? "Definir meta" : missing.toLocaleString("es-PE");
    const progressValue = completePct == null ? "S/D" : `${completePct.toFixed(0)}%`;

    const baseItems: OperationalKpiItem[] = [
      {
        label: phase.modality === "presencial" ? "QR válidos" : phase.modality === "telefono" ? "Efectivas" : "Respondidas",
        value: validValue,
        hint: "respuestas efectivas",
        status: observed == null ? "missing" : "ready",
      },
      {
        label: "Meta",
        value: metaValue,
        hint: "cuota del corte",
        status: meta == null ? "missing" : "ready",
      },
    ];

    const modalityItems: OperationalKpiItem[] = (() => {
      if (phase.modality === "telefono") {
        return [
          {
            label: "Faltante",
            value: missingValue,
            hint: "para cierre telefónico",
            status: missing == null ? "missing" : missing > 0 ? "warning" : "ready",
          },
          {
            label: "No efectivos",
            value: phase.attempts_var && phase.outcome_var ? "Config." : "S/D",
            hint: "requiere intentos/status de barrido",
            status: phase.attempts_var && phase.outcome_var ? "ready" : "missing",
          },
          {
            label: "Equipo",
            value: hasEnumerator ? "Listo" : "S/D",
            hint: hasEnumerator ? config.enumerator_var : "requiere responsable",
            status: hasEnumerator ? "ready" : "missing",
          },
        ];
      }
      if (phase.modality === "presencial") {
        return [
          {
            label: "Avance",
            value: progressValue,
            hint: "sobre meta del corte",
            status: completePct == null ? "missing" : completePct >= 100 ? "ready" : "warning",
          },
          {
            label: "Control local",
            value: hasOperationalRoster ? "Listo" : "S/D",
            hint: "visita, responsable o evidencia",
            status: hasOperationalRoster ? "ready" : "missing",
          },
          {
            label: "Faltante",
            value: missingValue,
            hint: "pendiente presencial/QR",
            status: missing == null ? "missing" : missing > 0 ? "warning" : "ready",
          },
        ];
      }
      if (phase.modality === "email" || phase.modality === "sms" || phase.modality === "whatsapp") {
        return [
          {
            label: "Avance",
            value: progressValue,
            hint: "sobre meta del corte",
            status: completePct == null ? "missing" : completePct >= 100 ? "ready" : "warning",
          },
          {
            label: "Universo",
            value: hasOperationalRoster ? "Listo" : "S/D",
            hint: "base de contactos/envios",
            status: hasOperationalRoster ? "ready" : "missing",
          },
          {
            label: "Faltante",
            value: missingValue,
            hint: "pendiente por cuota",
            status: missing == null ? "missing" : missing > 0 ? "warning" : "ready",
          },
        ];
      }
      return [
        {
          label: "Avance",
          value: progressValue,
          hint: "sobre meta del corte",
          status: completePct == null ? "missing" : completePct >= 100 ? "ready" : "warning",
        },
        {
          label: "Soporte",
          value: modalityDataSupportLabel(phase.modality),
          hint: "según modalidad activa",
          status: "warning",
        },
      ];
    })();

    return {
      id: phase.id || `phase-${index}`,
      title: source?.label || phase.stratum || "Corte operativo",
      detail: phaseWeekLabel(phase),
      modality: phase.modality,
      items: [...baseItems, ...modalityItems].slice(0, 5),
    };
  });
}

function sourceForPhase(phase: MonitoreoStrategyPhase, sources: MonitoreoSource[]) {
  const needle = normalizeMatch(phase.stratum);
  if (!needle) return null;
  return sources.find((source) => normalizeMatch(source.label) === needle)
    ?? sources.find((source) => sourceDimensionEntries(source.dimensions)
      .some(([, value]) => {
        const dimension = normalizeMatch(value);
        return dimension && (dimension === needle || needle.includes(dimension));
      }))
    ?? null;
}

function progressRowForPhase(
  phase: MonitoreoStrategyPhase,
  source: MonitoreoSource | null,
  rows: MonitoreoRow[],
) {
  const candidates = [
    phase.stratum,
    source?.label,
    ...sourceDimensionEntries(source?.dimensions).map(([, value]) => value),
  ].map(normalizeMatch).filter(Boolean);
  if (!candidates.length) return null;
  return rows.find((row) => Object.values(row).some((value) => {
    const normalized = normalizeMatch(value);
    return normalized && candidates.some((candidate) => candidate === normalized || candidate.includes(normalized) || normalized.includes(candidate));
  })) ?? null;
}

function normalizeMatch(value: unknown) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLocaleLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function modalityIcon(value: MonitoreoStrategyPhase["modality"] | string) {
  const normalized = normalizeMatch(value);
  if (normalized.includes("web") || normalized.includes("online") || normalized.includes("link")) return Globe2;
  if (normalized.includes("telefon")) return PhoneCall;
  if (normalized.includes("presencial") || normalized.includes("qr")) return QrCode;
  if (normalized.includes("correo") || normalized.includes("email") || normalized.includes("mail")) return Mail;
  if (normalized.includes("whatsapp") || normalized.includes("sms")) return ContactRound;
  return Route;
}

type OperationalStratum = {
  id: string;
  title: string;
  source: string;
  source_id: string;
  meta: number | null;
  detail: string;
  modalities: string[];
  filters: Record<string, string>;
};

function buildOperationalStrata(
  sources: MonitoreoSource[],
  config: MonitoreoConfig,
  acreditacion: MonitoreoAcreditacion,
): OperationalStratum[] {
  const out: OperationalStratum[] = [];
  const seenTitles = new Set<string>();
  for (const stratum of config.operational_model.strata) {
    if (!stratum.label && !stratum.variable && !stratum.value) continue;
    const source = stratum.source_id
      ? sources.find((item) => item.id === stratum.source_id)?.label ?? stratum.source_id
      : "Modelo operativo";
    const title = stratum.label || stratum.value || stratum.variable || "Corte operativo";
    seenTitles.add(title.trim().toLocaleLowerCase());
    const filters = stratum.variable && stratum.value ? { [stratum.variable]: stratum.value } : {};
    out.push({
      id: `model-${stratum.id}`,
      title,
      source,
      source_id: stratum.source_id,
      meta: goalForDimensions(config.goals, filters),
      detail: stratum.notes || (stratum.variable ? `${dimensionLabel(stratum.variable.replace(/^dim_/, ""))}: ${stratum.value || "S/D"}` : "Corte operativo"),
      modalities: [],
      filters,
    });
  }
  for (const src of sources) {
    const title = src.label || src.id;
    if (seenTitles.has(title.trim().toLocaleLowerCase())) continue;
    const dims = sourceDimensionEntries(src.dimensions);
    const provider = sourceProviderLabel(src.kind);
    const detail = dims.length
      ? dims.map(([key, value]) => `${dimensionLabel(key)}: ${value}`).join(" · ")
      : provider;
    const meta = goalForDimensions(config.goals, src.dimensions);
    out.push({
      id: `source-${src.id}`,
      title,
      source: provider,
      source_id: src.id,
      meta,
      detail,
      modalities: [],
      filters: goalFiltersFromDimensions(src.dimensions),
    });
  }
  for (const comp of acreditacion.componentes ?? []) {
    out.push({
      id: `acr-${comp.id}`,
      title: comp.actor,
      source: acreditacion.estudio.titulo,
      source_id: comp.id,
      meta: comp.meta.n_objetivo,
      detail: comp.tecnica || comp.meta.tipo || "Corte operativo",
      modalities: modalitiesFromIntentos(comp.seguimiento.intentos_canal),
      filters: { actor: comp.actor },
    });
  }
  for (const goal of config.goals) {
    const label = goalLabel(goal);
    const goalValues = Object.values(goal.filters).map(String);
    const covered = out.some((item) => (
      normalizeMatch(item.title) === normalizeMatch(label) ||
      goalValues.some((value) => {
        const normalized = normalizeMatch(value);
        return normalized && (
          normalizeMatch(item.title).includes(normalized) ||
          normalizeMatch(item.detail).includes(normalized)
        );
      })
    ));
    if (!covered) {
      out.push({
        id: `goal-${label}`,
        title: label,
        source: "Meta manual",
        source_id: "",
        meta: goal.meta,
        detail: Object.keys(goal.filters).map(dimensionLabel).join(" + ") || "Sin filtro",
        modalities: [],
        filters: goal.filters,
      });
    }
  }
  return out.slice(0, 12);
}

function sourceProviderLabel(kind: MonitoreoSourceKind) {
  if (kind === "kobo") return "KoboToolbox";
  if (kind === "google_sheets") return "Google Sheets";
  return "SurveyMonkey";
}

function goalFiltersFromDimensions(dimensions: Record<string, string> | undefined) {
  return Object.fromEntries(
    sourceDimensionEntries(dimensions).map(([key, value]) => [
      key.startsWith("dim_") ? key : `dim_${key}`,
      value,
    ]),
  );
}

function goalForDimensions(goals: MonitoreoGoal[], dimensions: Record<string, string> | undefined) {
  const entries = sourceDimensionEntries(dimensions);
  const match = goals.find((goal) => entries.some(([key, value]) => {
    const candidates = [key, `dim_${key}`];
    return candidates.some((candidate) => goal.filters[candidate] === value);
  }));
  return match?.meta ?? null;
}

function goalLabel(goal: MonitoreoGoal) {
  const entries = Object.entries(goal.filters);
  if (!entries.length) return "Meta general";
  return entries.map(([key, value]) => `${dimensionLabel(key.replace(/^dim_/, ""))}: ${value}`).join(" · ");
}

function modalitiesFromIntentos(intentos: MonitoreoAcreditacionIntentos) {
  return CANALES.filter((canal) => Number(intentos[canal] ?? 0) > 0);
}

function modalityLabel(value: MonitoreoStrategyPhase["modality"] | string) {
  const labels: Record<string, string> = {
    email: "Correo",
    whatsapp: "WhatsApp",
    sms: "SMS",
    telefono: "Teléfono",
    presencial: "Presencial",
    mixto: "Mixto",
  };
  return labels[value] ?? value;
}

function rosterSourceOption(value: MonitoreoOperationalCases["roster_source"]) {
  return ROSTER_SOURCE_OPTIONS.find((option) => option.value === value) ?? ROSTER_SOURCE_OPTIONS[0];
}

function modalityDataNeed(value: MonitoreoStrategyPhase["modality"] | string) {
  switch (value) {
    case "telefono":
      return "Teléfono se beneficia de base de barrido: responsable, status, intentos, fecha y observación.";
    case "presencial":
      return "Presencial puede usar base operativa local para visitas, responsable, estado y evidencias.";
    case "email":
      return "Correo suele partir de universo/contactos y respuesta de plataforma; no necesita barrido caso a caso.";
    case "whatsapp":
      return "WhatsApp puede combinar universo/contactos con eventos de envio, contacto y respuesta.";
    case "sms":
      return "SMS prioriza universo/contactos, entrega y respuesta; los KPIs de operador suelen ser secundarios.";
    default:
      return "Mixto combina capas: plataforma, universo y base operativa según la modalidad activa.";
  }
}

function modalityDataSupportLabel(value: MonitoreoStrategyPhase["modality"] | string) {
  switch (value) {
    case "telefono":
      return "Falta barrido";
    case "presencial":
      return "Falta base operativa";
    case "email":
    case "whatsapp":
    case "sms":
      return "Plataforma/contactos";
    default:
      return "Modelo mixto";
  }
}

function phaseWeekLabel(phase: MonitoreoStrategyPhase) {
  if (!phase.start_week && !phase.end_week) return "Sin semana";
  if (phase.start_week === phase.end_week || !phase.end_week) return `Semana ${phase.start_week}`;
  return `Semanas ${phase.start_week}-${phase.end_week}`;
}

function kpiModuleLabel(key: string) {
  return KPI_MODULES.find((item) => item.key === key)?.label ?? key;
}

function scopeOptionsForModality(modality: MonitoreoStrategyPhase["modality"]) {
  return STRATEGY_SCOPE_OPTIONS.filter((option) => option.modalities.includes(modality));
}

function scopeLabel(value: string, modality: MonitoreoStrategyPhase["modality"]) {
  return scopeOptionsForModality(modality).find((option) => option.value === value)?.label
    ?? STRATEGY_SCOPE_OPTIONS.find((option) => option.value === value)?.label
    ?? (value.length > 42 ? "Regla guardada" : value);
}

function kpiFocusLabel(value: string) {
  const pretty = KPI_FOCUS_LABELS[value] ?? value.replace(/_/g, " ");
  return pretty.length > 26 ? `${pretty.slice(0, 23)}...` : pretty;
}

function focusOptionsForModality(modality: MonitoreoStrategyPhase["modality"], selected: string[]) {
  const base = KPI_FOCUS_OPTIONS_BY_MODALITY[modality] ?? [];
  return Array.from(new Set([...base, ...selected]));
}

function finalStateLabel(value: string) {
  return FINAL_STATE_OPTIONS.find((option) => option.value === value)?.label ?? value;
}

function outcomeLabel(value: string, events: MonitoreoOperationalEvent[] = []) {
  const eventLabel = events.find((event) => event.outcome === value)?.label;
  if (eventLabel) return prettyOperationalLabel(eventLabel);
  return OUTCOME_PRESETS.find((option) => option.value === value)?.label ?? prettyOperationalLabel(value);
}

function outcomeOptions(events: MonitoreoOperationalEvent[], extras: string[] = []) {
  const out: Array<{ value: string; label: string }> = [];
  const seen = new Set<string>();
  const push = (value: string, label: string) => {
    const clean = value.trim();
    if (!clean || seen.has(clean)) return;
    seen.add(clean);
    out.push({ value: clean, label });
  };
  for (const event of events) push(event.outcome, prettyOperationalLabel(event.label || outcomeLabel(event.outcome)));
  for (const option of OUTCOME_PRESETS) push(option.value, option.label);
  for (const extra of extras) push(extra, outcomeLabel(extra, events));
  return out;
}

function prettyOperationalLabel(value: string) {
  if (!value) return "";
  return value
    .replace(/\bNumero\b/g, "Número")
    .replace(/\bnumero\b/g, "número")
    .replace(/\bdespues\b/g, "después")
    .replace(/\bvalida\b/g, "válida")
    .replace(/\bvalidos\b/g, "válidos")
    .replace(/\btelefono\b/g, "teléfono")
    .replace(/\bTelefono\b/g, "Teléfono")
    .replace(/\btelefonico\b/g, "telefónico")
    .replace(/\bTelefonico\b/g, "Telefónico");
}

function withCurrentOption(options: string[], value: string) {
  const clean = value.trim();
  if (!clean || options.includes(clean)) return options;
  return [...options, clean];
}

function strategyPhaseOptionLabel(phase: MonitoreoStrategyPhase) {
  const stratum = phase.stratum?.trim();
  const modality = modalityLabel(phase.modality);
  if (!stratum) return modality;
  return `${stratum} · ${modality}`;
}

function compactListLabel(values: string[], limit = 2) {
  const clean = values.map((value) => value.trim()).filter(Boolean);
  if (!clean.length) return "";
  if (clean.length <= limit) return clean.join(", ");
  return `${clean.slice(0, limit).join(", ")} +${clean.length - limit}`;
}

function AcreditacionOperationalModel({
  sources,
  config,
  setConfig,
  acreditacion,
  dashboard,
  variables,
  onConfigPersisted,
}: {
  sources: MonitoreoSource[];
  config: MonitoreoConfig;
  setConfig: (next: MonitoreoConfig) => void;
  acreditacion: MonitoreoAcreditacion;
  dashboard: MonitoreoDashboard | null;
  variables: MonitoreoVariable[];
  onConfigPersisted: (next: MonitoreoState) => void;
}) {
  const [savingActorMeta, setSavingActorMeta] = useState<string | null>(null);
  const [metaError, setMetaError] = useState("");
  const cards = dashboard
    ? buildActorProgressCards(sources, config, acreditacion, dashboard)
    : buildActorModelCards(sources, config, acreditacion);
  const totals = actorProgressTotals(cards);
  const unitLexicon = monitoringUnitLexicon(config.monitoreo_profile);
  const missingGoals = cards.filter((card) => card.meta == null).length;
  const surveyCount = sources.filter((source) => source.kind === "surveymonkey" && source.enabled).length;
  const sweepCount = sources.filter((source) => source.kind === "google_sheets" && source.role === "barrido" && source.enabled).length;

  async function setActorMeta(actor: string, meta: number | null, metaPct: number | null = null) {
    const nextConfig = mergeConfig({ ...config, goals: upsertGoalForActor(config.goals, actor, meta, metaPct, unitLexicon.singular === "carrera" ? "carrera" : "actor") });
    setConfig(nextConfig);
    setSavingActorMeta(actor);
    setMetaError("");
    try {
      const result = await apiMonitoreoConfig(nextConfig);
      onConfigPersisted(result.state);
    } catch (e) {
      setConfig(config);
      setMetaError((e as Error).message);
      throw e;
    } finally {
      setSavingActorMeta(null);
    }
  }

  return (
    <div className="mon-stage mon-stage--model mon-stage--acr-model">
      <Panel
        className="mon-fill-panel mon-acr-model-panel"
        eyebrow="Modelo operativo"
        title={<span className="mon-title-icon"><Target size={16} /> {unitLexicon.goalLabel}</span>}
        actions={(
          <div className="mon-acr-model-actions">
            <span>{cards.length} {unitLexicon.plural}</span>
            <span>{surveyCount} encuestas</span>
            <span>{sweepCount} barrido</span>
            <span>{missingGoals ? `${missingGoals} sin meta` : "Metas listas"}</span>
            <span>{totals.mechanisms} canales</span>
          </div>
        )}
      >
        <div className="mon-acr-model-map" aria-label="Mapa operativo de acreditacion">
          <ActorDashboardTile label={unitLexicon.pluralTitle} value={formatMetric(cards.length)} hint="modelo base" tone="base" />
          <ActorDashboardTile label="Universo" value={formatMetric(totals.universe)} hint="desde Sheets" tone="ready" />
          <ActorDashboardTile label={unitLexicon.goalShortLabel} value={totals.meta == null ? "S/M" : formatMetric(totals.meta)} hint={missingGoals ? `${missingGoals} pendientes` : "configuradas"} tone={missingGoals ? "warning" : "target"} />
          <ActorDashboardTile label="Canales" value={formatMetric(totals.mechanisms)} hint="SurveyMonkey y barrido" tone="base" />
        </div>
        <div className="mon-acr-model-flow" aria-label="Relación meta mecanismo barrido regla valida">
          <span className={missingGoals ? "is-warning" : "is-ready"}>
            <Target size={14} />
            <strong>Meta</strong>
            <em>{missingGoals ? `${missingGoals} ${missingGoals === 1 ? unitLexicon.singular : unitLexicon.plural} sin meta` : `${unitLexicon.goalLabel.toLowerCase()} listas`}</em>
          </span>
          <span className={totals.mechanisms ? "is-ready" : "is-warning"}>
            <Route size={14} />
            <strong>Mecanismo</strong>
            <em>{totals.mechanisms ? `${formatMetric(totals.mechanisms)} fuentes conectadas` : "sin mecanismo de avance"}</em>
          </span>
          <span className={sweepCount ? "is-ready" : "is-warning"}>
            <PhoneCall size={14} />
            <strong>Barrido</strong>
            <em>{sweepCount ? `${sweepCount} hoja${sweepCount === 1 ? "" : "s"} de barrido` : "falta barrido telefónico"}</em>
          </span>
          <span className={config.operational_model.state_rules.length ? "is-ready" : "is-warning"}>
            <SlidersHorizontal size={14} />
            <strong>Regla válida</strong>
            <em>{config.operational_model.state_rules.length ? `${config.operational_model.state_rules.length} estados configurados` : "definir qué cuenta como avance"}</em>
          </span>
        </div>

        {metaError && <div className="mon-sm-error">{metaError}</div>}
        <PlatformRejectionRulePanel
          config={config}
          setConfig={setConfig}
          variables={variables}
          onConfigPersisted={onConfigPersisted}
        />
        <div className="mon-acr-model-actor-grid">
          {cards.length ? cards.map((card) => (
            <AcreditacionModelActorCard
              key={card.id}
              card={card}
              saving={Boolean(savingActorMeta) && normalizeMatch(savingActorMeta) === normalizeMatch(card.actor)}
              disabled={Boolean(savingActorMeta)}
              unitLexicon={unitLexicon}
              onMetaChange={setActorMeta}
            />
          )) : (
            <EmptyState
              icon={<Layers3 size={18} />}
              title={`Sin ${unitLexicon.plural} detectad${unitLexicon.singular === "carrera" ? "as" : "os"}`}
              hint={`Carga la base trabajada para armar el modelo ${unitLexicon.byUnit}.`}
              variant="inline"
            />
          )}
        </div>
      </Panel>
    </div>
  );
}

type PlatformRejectionRuleDraft = {
  id: string;
  question: string;
  answers: string;
};

type PlatformRejectionQuestionOption = {
  value: string;
  label: string;
  choices: string[];
  support: number;
};

function PlatformRejectionRulePanel({
  config,
  setConfig,
  variables,
  onConfigPersisted,
}: {
  config: MonitoreoConfig;
  setConfig: (next: MonitoreoConfig) => void;
  variables: MonitoreoVariable[];
  onConfigPersisted: (next: MonitoreoState) => void;
}) {
  const rulesKey = JSON.stringify(config.monitoreo_profile.rejection_rules ?? []);
  const [drafts, setDrafts] = useState<PlatformRejectionRuleDraft[]>(() => platformRejectionDrafts(config.monitoreo_profile));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const questionOptions = platformQuestionOptions(variables);
  const configured = drafts.filter((draft) => draft.question.trim() && draft.answers.trim()).length;
  const hasDraftOutsideCatalog = drafts.some((draft) => draft.question.trim() && !questionOptions.some((option) => option.value === draft.question.trim()));

  useEffect(() => {
    setDrafts(platformRejectionDrafts(config.monitoreo_profile));
  }, [rulesKey, config.monitoreo_profile]);

  function updateDraft(id: string, patch: Partial<PlatformRejectionRuleDraft>) {
    setDrafts((current) => current.map((draft) => draft.id === id ? { ...draft, ...patch } : draft));
  }

  function addDraft() {
    setDrafts((current) => [...current, newPlatformRejectionDraft()]);
  }

  function removeDraft(id: string) {
    setDrafts((current) => {
      const next = current.filter((draft) => draft.id !== id);
      return next.length ? next : [newPlatformRejectionDraft()];
    });
  }

  async function saveRules() {
    setSaving(true);
    setError("");
    const profile = mergeProfile(config.monitoreo_profile);
    const rejection_rules = drafts
      .map((draft) => ({
        enabled: true,
        actor: "",
        question_patterns: splitListInput(draft.question),
        rejection_answers: splitListInput(draft.answers),
      }))
      .filter((rule) => rule.question_patterns.length && rule.rejection_answers.length);
    const nextConfig = mergeConfig({
      ...config,
      monitoreo_profile: {
        ...profile,
        rejection_rules,
      },
    });
    setConfig(nextConfig);
    try {
      const result = await apiMonitoreoConfig(nextConfig);
      onConfigPersisted(result.state);
      setConfig(mergeConfig(result.config));
    } catch (e) {
      setConfig(config);
      setError((e as Error).message);
    } finally {
      setSaving(false);
    }
  }

  return (
    <section className={`mon-platform-rejection-rule${configured ? " is-configured" : " is-empty"}`} aria-label="Definición de rechazo de plataforma">
      <header>
        <div>
          <span>Rechazo de plataforma</span>
          <strong>{configured ? `${configured} regla${configured === 1 ? "" : "s"} activa${configured === 1 ? "" : "s"}` : "Sin regla definida"}</strong>
          <p>Define qué pregunta filtro y qué respuesta marcan rechazo dentro de las respuestas de plataforma.</p>
        </div>
        <button type="button" onClick={saveRules} disabled={saving}>
          {saving ? <Loader2 size={13} className="pulso-spin" /> : <Save size={13} />}
          Guardar regla
        </button>
      </header>
      <div className="mon-platform-rule-list">
        {drafts.map((draft, index) => (
          <article key={draft.id} className="mon-platform-rule-row">
            <div className="mon-platform-rule-index" aria-label={`Condición ${index + 1}`}>
              <span>Condición {String(index + 1).padStart(2, "0")}</span>
            </div>
            <label>
              <span>Pregunta de selección única</span>
              <select
                value={draft.question}
                onChange={(e) => {
                  const nextQuestion = e.target.value;
                  const option = questionOptions.find((item) => item.value === nextQuestion);
                  updateDraft(draft.id, {
                    question: nextQuestion,
                    answers: option?.choices.includes(draft.answers) ? draft.answers : option?.choices[0] ?? "",
                  });
                }}
              >
                <option value="">Seleccionar pregunta</option>
                {withCurrentQuestionOption(questionOptions, draft.question).map((option) => (
                  <option key={option.value} value={option.value}>{option.label}</option>
                ))}
              </select>
            </label>
            <label>
              <span>Respuesta que rechaza</span>
              <select
                value={draft.answers}
                onChange={(e) => updateDraft(draft.id, { answers: e.target.value })}
                disabled={!draft.question}
              >
                <option value="">Seleccionar respuesta</option>
                {platformAnswerOptions(questionOptions, draft).map((answer) => (
                  <option key={answer} value={answer}>{answer}</option>
                ))}
              </select>
            </label>
            <button type="button" className="mon-icon-action" aria-label="Quitar regla de rechazo" onClick={() => removeDraft(draft.id)}>
              <Trash2 size={13} />
            </button>
          </article>
        ))}
      </div>
      <footer>
        <button type="button" onClick={addDraft}>
          <Plus size={13} />
          Agregar condición
        </button>
        <span>
          {questionOptions.length
            ? `${questionOptions.length} preguntas de selección única detectadas`
            : hasDraftOutsideCatalog
              ? "Regla existente fuera del catálogo"
              : "Sin preguntas de selección única detectadas"}
        </span>
      </footer>
      {error && <div className="mon-sm-error">{error}</div>}
    </section>
  );
}

function newPlatformRejectionDraft(): PlatformRejectionRuleDraft {
  return {
    id: `rechazo-plataforma-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    question: "",
    answers: "No",
  };
}

function platformRejectionDrafts(profile: MonitoreoProfile): PlatformRejectionRuleDraft[] {
  const rules = arrayOrEmpty<Record<string, unknown>>(profile.rejection_rules)
    .map((rule, index) => {
      const question = arrayOrEmpty<unknown>(rule.question_patterns).map((item) => String(item ?? "").trim()).filter(Boolean).join(", ");
      const answers = arrayOrEmpty<unknown>(rule.rejection_answers).map((item) => String(item ?? "").trim()).filter(Boolean).join(", ");
      return {
        id: `rechazo-plataforma-${index}`,
        question,
        answers: answers || "No",
      };
    });
  return rules.length ? rules : [newPlatformRejectionDraft()];
}

function platformQuestionOptions(variables: MonitoreoVariable[]): PlatformRejectionQuestionOption[] {
  return variables
    .map((variable) => {
      const choices = arrayOrEmpty<string>(variable.values)
        .map((item) => String(item ?? "").trim())
        .filter(Boolean);
      return {
        value: variable.name,
        label: platformQuestionLabel(variable),
        choices,
        support: Math.max(0, (variable.n_unique ?? 0) - (variable.n_missing ? 0 : 0)),
      };
    })
    .filter((option) => {
      const key = normalizeMatch(option.value);
      return /^q\d{4}$/i.test(option.value)
        && option.choices.length >= 2
        && option.choices.length <= 10
        && !key.includes("otro especifique");
    })
    .sort((a, b) => {
      const aIsFilter = normalizeMatch(a.value) === "q0001" ? -1 : 0;
      const bIsFilter = normalizeMatch(b.value) === "q0001" ? -1 : 0;
      return aIsFilter - bIsFilter || a.value.localeCompare(b.value, "es");
    });
}

function platformQuestionLabel(variable: MonitoreoVariable) {
  const name = variable.name;
  const directLabel = String(variable.label ?? "").trim();
  if (directLabel && directLabel !== name) return directLabel;
  const [code, rawLabel] = name.split("__", 2);
  return rawLabel ? humanizeQuestionSlug(rawLabel) : code;
}

function humanizeQuestionSlug(value: string) {
  return value
    .replace(/_/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b([a-záéíóúñ])/g, (letter) => letter.toLocaleUpperCase("es"));
}

function withCurrentQuestionOption(options: PlatformRejectionQuestionOption[], value: string) {
  const clean = value.trim();
  if (!clean || options.some((option) => option.value === clean)) return options;
  return [{
    value: clean,
    label: clean,
    choices: [],
    support: 0,
  }, ...options];
}

function platformAnswerOptions(options: PlatformRejectionQuestionOption[], draft: PlatformRejectionRuleDraft) {
  const selected = options.find((option) => option.value === draft.question);
  const choices = selected?.choices ?? [];
  const current = draft.answers.trim();
  return current && !choices.includes(current) ? [current, ...choices] : choices;
}

function splitListInput(value: string) {
  return value
    .split(/[,;\n]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function AcreditacionModelActorCard({
  card,
  saving,
  disabled,
  unitLexicon = monitoringUnitLexicon(),
  onMetaChange,
}: {
  card: ActorProgressCard;
  saving: boolean;
  disabled: boolean;
  unitLexicon?: MonitoringUnitLexicon;
  onMetaChange: (actor: string, meta: number | null, metaPct?: number | null) => Promise<void>;
}) {
  const connectedMechanisms = card.mechanisms.filter((item) => item.role !== "Universo");
  const universeSources = card.mechanisms.filter((item) => item.role === "Universo");
  const baseMechanisms = [...universeSources, ...connectedMechanisms.filter((item) => item.role === "Barrido")];
  const responseMechanisms = connectedMechanisms.filter((item) => item.role !== "Barrido");
  const channels = Array.from(new Set(connectedMechanisms.map((item) => item.channel || modalityLabel(item.modality)).filter(Boolean)));
  const statusTone = card.meta == null ? "warning" : card.statusTone === "complete" ? "ready" : "base";
  const [metaEditing, setMetaEditing] = useState(card.meta == null);
  const [metaDraft, setMetaDraft] = useState(card.meta == null ? "" : String(card.meta));
  const [percentDraft, setPercentDraft] = useState(formatActorMetaPercent(card.meta, card.universe));

  useEffect(() => {
    setMetaDraft(card.meta == null ? "" : String(card.meta));
    setPercentDraft(formatActorMetaPercent(card.meta, card.universe));
    setMetaEditing(card.meta == null);
  }, [card.actor, card.meta, card.universe]);

  const setAbsoluteMetaDraft = (raw: string) => {
    setMetaDraft(raw);
    if (raw.trim() === "") {
      setPercentDraft("");
      return;
    }
    if (card.universe != null && card.universe > 0) {
      setPercentDraft(formatActorMetaPercent(Math.max(0, Math.round(Number(raw) || 0)), card.universe));
    }
  };

  const setPercentMetaDraft = (raw: string) => {
    setPercentDraft(raw);
    if (raw.trim() === "") {
      setMetaDraft("");
      return;
    }
    if (card.universe == null || card.universe <= 0) return;
    const pct = Math.max(0, Number(raw) || 0);
    setMetaDraft(String(Math.max(0, Math.round((card.universe * pct) / 100))));
  };

  const confirmMeta = async () => {
    if (metaDraft.trim() === "") {
      try {
        await onMetaChange(card.actor, null);
      } catch {
        // El error se muestra en el panel padre.
      }
      setMetaEditing(true);
      return;
    }
    const nextMeta = Math.max(0, Math.round(Number(metaDraft) || 0));
    const nextMetaPct = percentDraft.trim() === ""
      ? null
      : Math.max(0, Number(percentDraft) || 0);
    try {
      await onMetaChange(card.actor, nextMeta, nextMetaPct);
      setMetaEditing(false);
    } catch {
      setMetaEditing(true);
    }
  };

  const adjustMeta = () => {
    setMetaDraft(card.meta == null ? "" : String(card.meta));
    setPercentDraft(formatActorMetaPercent(card.meta, card.universe));
    setMetaEditing(true);
  };

  const renderMechanism = (item: ActorMechanism) => {
    const Icon = modalityIcon(item.modality);
    return (
      <div key={item.id} className={`mon-acr-model-source-item is-${modelMechanismKind(item)}`}>
        <Icon size={13} />
        <span>{item.label}</span>
        <em>{modelMechanismRoleLabel(item)}</em>
      </div>
    );
  };

  return (
    <article className={`mon-acr-model-actor is-${statusTone}${metaEditing ? " is-editing-meta" : ""}`}>
      <header className="mon-acr-model-actor-head">
        <div>
          <span>{unitLexicon.singularTitle}</span>
          <strong>{card.actor}</strong>
        </div>
        <em>{card.meta == null ? "Meta pendiente" : metaEditing ? "Ajustando meta" : "Meta confirmada"}</em>
      </header>
      <div className="mon-acr-model-actor-metrics">
        <ActorFlowNode label="Universo" value={formatMetric(card.universe)} tone="base" />
        <ActorFlowNode label={unitLexicon.goalShortLabel} value={formatActorMetaValueLabel(card)} tone={card.meta == null ? "warning" : "target"} />
        <ActorFlowNode label="Efectivas" value={formatMetric(card.completed)} tone="ready" />
      </div>
      <div className="mon-acr-model-minimum-editor">
        <label>
          <span>Mínimo N</span>
          <input
            type="number"
            min={0}
            step={1}
            value={metaDraft}
            onChange={(e) => setAbsoluteMetaDraft(e.target.value)}
            placeholder="Ej. 80"
            disabled={disabled || !metaEditing}
          />
        </label>
        <label>
          <span>% universo</span>
          <input
            type="number"
            min={0}
            max={100}
            step={0.1}
            value={percentDraft}
            onChange={(e) => setPercentMetaDraft(e.target.value)}
            placeholder="Ej. 30"
            disabled={disabled || !metaEditing || card.universe == null || card.universe <= 0}
          />
        </label>
        <button
          type="button"
          className={metaEditing ? "is-confirm" : "is-adjust"}
          onClick={metaEditing ? confirmMeta : adjustMeta}
          disabled={disabled || (metaEditing && card.meta == null && !metaDraft.trim() && !percentDraft.trim())}
        >
          {saving ? <Loader2 size={13} className="pulso-spin" /> : metaEditing ? "Confirmar" : "Ajustar"}
        </button>
      </div>
      <div className="mon-acr-model-channel-strip">
        {channels.length ? channels.map((channel) => <span key={channel}>{channel}</span>) : <span>Sin canal</span>}
      </div>
      <div className="mon-acr-model-source-list">
        {baseMechanisms.length > 0 && (
          <section className="mon-acr-model-source-group mon-acr-model-source-group--base">
            <header>
              <span>Base y barrido</span>
              <em>{baseMechanisms.length}</em>
            </header>
            {baseMechanisms.map(renderMechanism)}
          </section>
        )}
        {responseMechanisms.length > 0 && (
          <section className="mon-acr-model-source-group mon-acr-model-source-group--responses">
            <header>
              <span>Fuentes de respuesta</span>
              <em>{responseMechanisms.length}</em>
            </header>
            {responseMechanisms.map(renderMechanism)}
          </section>
        )}
      </div>
    </article>
  );
}

function formatActorMetaPercent(meta: number | null, universe: number | null) {
  if (meta == null || universe == null || universe <= 0) return "";
  const value = Math.round((meta / universe) * 1000) / 10;
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}

function modelMechanismKind(item: ActorMechanism) {
  if (item.role === "Universo") return "base";
  if (item.role === "Barrido") return "sweep";
  return "response";
}

function modelMechanismRoleLabel(item: ActorMechanism) {
  if (item.role === "Universo") return "Base trabajada";
  if (item.role === "Barrido") return "Barrido telefónico";
  return item.provider === "SurveyMonkey" ? "Encuesta" : "Respuesta";
}

function buildActorModelCards(
  sources: MonitoreoSource[],
  config: MonitoreoConfig,
  acreditacion: MonitoreoAcreditacion,
): ActorProgressCard[] {
  const actors = new Map<string, string>();
  const addActor = (value: unknown) => {
    const label = cleanActorDimensionValue(value);
    const key = normalizeMatch(label);
    if (label && key && !actors.has(key)) actors.set(key, label);
  };

  sources.forEach((source) => addActor(actorFromSource(source)));
  acreditacion.componentes.forEach((component) => addActor(component.actor));
  config.goals.forEach((goal) => {
    Object.entries(goal.filters).forEach(([key, value]) => {
      if (normalizeMatch(key).includes("actor") || normalizeMatch(key).includes("segment")) addActor(value);
    });
  });

  return Array.from(actors.entries()).map(([key, actor]) => {
    const component = acreditacion.componentes.find((item) => normalizeMatch(item.actor) === key) ?? null;
    const actorSources = sources.filter((source) => normalizeMatch(actorFromSource(source)) === key);
    const mechanisms = dedupeActorResponseMechanisms(actorSources.map((source) => ({
      id: source.id,
      label: compactMechanismLabel(source.label || source.id),
      provider: sourceProviderLabel(source.kind),
      role: sourceRoleForActor(source, source.label),
      modality: modalityForActorMechanism(source, source.dimensions?.canal ?? "", source.label),
      observed: null,
      channel: sourceChannelDisplay(source),
    }))).sort((a, b) => mechanismRank(a.role) - mechanismRank(b.role) || a.label.localeCompare(b.label));
    const universe = firstNumber([
      component?.marco.marco_contactable,
      component?.marco.marco_actualizado,
      component?.marco.universo_bruto,
    ]);
    const actorGoalMeta = goalForActor(config.goals, actor);
    const actorGoalMetaPct = goalMetaPctForActor(config.goals, actor);
    const actorGoalMetaFromPct = metaFromPercent(actorGoalMetaPct, universe);
    const meta = firstNumber([
      actorGoalMeta,
      actorGoalMetaFromPct,
      component?.meta.n_objetivo,
      component?.marco.meta_efectiva,
    ]);
    const metaPct = actorGoalMetaPct ?? safePercent(meta, universe);
    const statusTone: ActorProgressCard["statusTone"] = meta == null ? "muted" : "steady";
    return {
      id: `actor-model-${key}`,
      actor,
      universe,
      meta,
      metaPct,
      completed: null,
      partial: null,
      refusals: null,
      refusalsPlatform: null,
      refusalsPhone: null,
      respondedPlatform: null,
      phoneEffective: null,
      phoneConciliated: null,
      phoneWithoutComplete: null,
      unanswered: null,
      actorProgress: null,
      coverageProgress: null,
      missing: null,
      status: meta == null ? "Meta pendiente" : "Meta definida",
      statusTone,
      mechanisms,
    };
  }).sort((a, b) => a.actor.localeCompare(b.actor));
}

function toggleValue(values: string[], value: string) {
  return values.includes(value) ? values.filter((item) => item !== value) : [...values, value];
}

function phaseOutputSummary(phase: MonitoreoStrategyPhase, config: MonitoreoConfig) {
  const modules = phase.kpi_modules.map(kpiModuleLabel);
  const focus = phase.kpi_focus.length ? `; foco: ${phase.kpi_focus.map(kpiFocusLabel).join(", ")}` : "";
  const scope = phase.target_rule ? `; alcance: ${scopeLabel(phase.target_rule, phase.modality)}` : "";
  const breakdown = phase.breakdown_vars.length ? `; desgloses: ${phase.breakdown_vars.join(", ")}` : "";
  const operator = config.enumerator_var ? ` y operador (${config.enumerator_var})` : "";
  const attempts = phase.attempts_var ? `; intentos: ${phase.attempts_var}` : "";
  const outcome = phase.outcome_var ? `; resultado: ${phase.outcome_var}` : "";
  const base = modules.length ? modules.join(", ") : "avance basico";
  return `${modalityLabel(phase.modality)}: ${base}${scope}${focus}${breakdown}${operator}${attempts}${outcome}.`;
}

function OperationalModelPanel({
  mode,
  onModeChange,
  sources,
  config,
  acreditacion,
  dashboard,
  variables,
  setConfig,
  onConfigPersisted,
}: {
  mode: OperationalModelMode;
  onModeChange: (mode: OperationalModelMode) => void;
  sources: MonitoreoSource[];
  config: MonitoreoConfig;
  acreditacion: MonitoreoAcreditacion;
  dashboard: MonitoreoDashboard | null;
  variables: MonitoreoVariable[];
  setConfig: (next: MonitoreoConfig) => void;
  onConfigPersisted: (next: MonitoreoState) => void;
}) {
  const isAcreditacion = config.monitoreo_profile.family === "acreditacion" || acreditacion.enabled;
  if (isAcreditacion) {
    return (
      <AcreditacionOperationalModel
        sources={sources}
        config={config}
        setConfig={setConfig}
        acreditacion={acreditacion}
        dashboard={dashboard}
        variables={variables}
        onConfigPersisted={onConfigPersisted}
      />
    );
  }

  const strata = buildOperationalStrata(sources, config, acreditacion);
  return (
    <div className="mon-stage mon-stage--model">
      <StageModeBar
        options={OPERATIONAL_MODEL_MODES}
        active={mode}
        onChange={onModeChange}
        summary={
          <>
            <span>{sources.filter((source) => source.enabled).length}/{sources.length} fuentes</span>
            <span>{strata.length} cortes</span>
            <span>{config.strategy_phases.length} mecanismos</span>
          </>
        }
      />
      <div className={`mon-model-stage-grid${mode === "estructura" || mode === "casos" || mode === "enlaces" || mode === "reglas" ? " is-wide" : ""}`}>
        <Panel
          className="mon-fill-panel mon-model-panel"
          eyebrow="Modelo operativo"
          title={<span className="mon-title-icon"><ListChecks size={16} /> {OPERATIONAL_MODEL_MODES.find((item) => item.key === mode)?.label}</span>}
        >
          <div className="mon-model-panel-body">
            {mode === "estrategias" && (
              <div className="mon-model-single">
                <StrategyPlanner
                  config={config}
                  setConfig={setConfig}
                  strata={strata}
                  variables={variables}
                />
              </div>
            )}

            {mode === "estructura" && (
              <div className="mon-model-two-column mon-model-two-column--structure">
              <div className="mon-model-block mon-model-block--detected">
                <div className="mon-model-block-head">
                  <span>Cortes detectados</span>
                  <strong>{strata.length || "Sin cortes"}</strong>
                </div>
                <div className={`mon-strata-list mon-contained-list${strata.length ? "" : " is-empty"}`}>
                  {strata.length ? strata.map((item) => (
                    <div key={item.id} className="mon-stratum-card">
                      <div>
                        <strong>{item.title}</strong>
                        <span>{item.source}</span>
                      </div>
                      <em>{item.meta == null ? "Meta S/D" : `${item.meta.toLocaleString("es-PE")} casos`}</em>
                      <p>{item.detail}</p>
                      {item.modalities.length > 0 && (
                        <div className="mon-modality-chips">
                          {item.modalities.map((modality) => <span key={modality}>{modalityLabel(modality)}</span>)}
                        </div>
                      )}
                    </div>
                  )) : (
                    <div className="mon-sm-empty">Conecta fuentes o agrega cortes para completar la estructura.</div>
                  )}
                </div>
              </div>
                <OperationalContractPanel
                  mode={mode}
                  sources={sources}
                  config={config}
                  setConfig={setConfig}
                  variables={variables}
                  strata={strata}
                  onConfigPersisted={onConfigPersisted}
                />
              </div>
            )}

            {mode !== "estrategias" && mode !== "estructura" && (
              <OperationalContractPanel
                mode={mode}
                sources={sources}
                config={config}
                setConfig={setConfig}
                variables={variables}
                strata={strata}
                onConfigPersisted={onConfigPersisted}
              />
            )}
          </div>
        </Panel>
        {mode !== "estructura" && mode !== "casos" && mode !== "enlaces" && mode !== "reglas" && (
          <ModelInspector
            mode={mode}
            config={config}
            setConfig={setConfig}
            variables={variables}
            strata={strata}
          />
        )}
      </div>
    </div>
  );
}

function OperationalFlowSummary({
  sources,
  activeSources,
  strata,
  goals,
  cases,
  phases,
  variables,
  alerts,
}: {
  sources: number;
  activeSources: number;
  strata: number;
  goals: number;
  cases: MonitoreoOperationalCases;
  phases: number;
  variables: number;
  alerts: number;
}) {
  return (
    <div className="mon-operational-flow">
      <ModelStep icon={<PlugZap size={15} />} label="Fuentes" value={`${activeSources}/${sources} activas`} />
      <ModelStep icon={<Layers3 size={15} />} label="Cortes y metas" value={`${strata} cortes · ${goals} metas`} />
      <ModelStep icon={<Route size={15} />} label="Mecanismos" value={`${phases} configurados`} />
      <ModelStep icon={<ContactRound size={15} />} label="Base de barrido" value={cases.enabled ? (cases.case_id_var || "Activa") : "Opcional"} />
      <ModelStep icon={<SlidersHorizontal size={15} />} label="Estados" value={`${variables} variables`} />
      <ModelStep icon={<AlertTriangle size={15} />} label="Alertas" value={`${alerts} alertas`} />
    </div>
  );
}

function OperationalContractPanel({
  mode,
  sources,
  config,
  setConfig,
  variables,
  strata,
  onConfigPersisted,
}: {
  mode: OperationalModelMode;
  sources: MonitoreoSource[];
  config: MonitoreoConfig;
  setConfig: (next: MonitoreoConfig) => void;
  variables: MonitoreoVariable[];
  strata: OperationalStratum[];
  onConfigPersisted: (next: MonitoreoState) => void;
}) {
  const model = config.operational_model;
  const variableNames = variables.map((variable) => variable.name);
  const sourceOptions = sources.map((source) => ({ id: source.id, label: source.label || source.id }));
  const showStructure = mode === "estructura";
  const showLinks = mode === "enlaces";
  const showCases = mode === "casos";
  const showStrategies = mode === "estrategias";
  const showRules = mode === "reglas";
  const strategyLabelOptions = Array.from(new Set([
    ...STRATEGY_LABEL_OPTIONS,
    ...config.strategy_phases.map(strategyPhaseOptionLabel).filter(Boolean),
    ...strata.map((item) => `Seguimiento · ${item.title}`),
  ]));

  function setModel(patch: Partial<MonitoreoOperationalModel>) {
    setConfig({
      ...config,
      operational_model: mergeOperationalModel({ ...model, ...patch }),
    });
  }

  function updateCases(patch: Partial<MonitoreoOperationalCases>) {
    setModel({ cases: { ...model.cases, ...patch } });
  }

  function updateStratum(index: number, patch: Partial<MonitoreoOperationalStratum>) {
    setModel({
      strata: model.strata.map((item, i) => i === index ? { ...item, ...patch } : item),
    });
  }

  function addStratum() {
    setModel({
      strata: [
        ...model.strata,
        {
          id: `corte-${Date.now()}`,
          label: "",
          source_id: sourceOptions[0]?.id ?? "",
          variable: variableNames[0] ?? "",
          value: "",
          notes: "",
        },
      ],
    });
  }

  function updateStrategy(index: number, patch: Partial<MonitoreoOperationalStrategy>) {
    setModel({
      strategies: model.strategies.map((item, i) => i === index ? { ...item, ...patch } : item),
    });
  }

  function addStrategy() {
    setModel({
      strategies: [
        ...model.strategies,
        {
          id: `estrategia-${Date.now()}`,
          label: "",
          objective: "",
          owner: "",
          status: "draft",
        },
      ],
    });
  }

  function updateEvent(index: number, patch: Partial<MonitoreoOperationalEvent>) {
    setModel({
      events: model.events.map((item, i) => i === index ? { ...item, ...patch } : item),
    });
  }

  function updateRule(index: number, patch: Partial<MonitoreoStateRule>) {
    setModel({
      state_rules: model.state_rules.map((item, i) => i === index ? { ...item, ...patch } : item),
    });
  }

  return (
    <div className="mon-operational-contract">
      <div className="mon-contract-head">
        <div>
          <span className="pulso-section-eyebrow">Configuración operativa</span>
          <strong>
            {showStructure && "Metas y mecanismos de recolección"}
            {showLinks && "Enlaces, envíos y links"}
            {showCases && "Base de barrido"}
            {showStrategies && "Calendario de recolección"}
            {showRules && "Estados que cuentan como avance"}
          </strong>
        </div>
        <span>Local al proyecto</span>
      </div>

      <div className={`mon-contract-grid${showRules ? " mon-contract-grid--rules" : ""}${showLinks ? " mon-contract-grid--links" : ""}${showCases ? " mon-contract-grid--cases" : ""}`}>
        {showStructure && (
        <div className="mon-contract-block mon-contract-block--wide">
          <div className="mon-contract-block-head">
            <span>Cortes, metas y mecanismos</span>
            <span className="mon-contract-counter">{config.goals.length}/{strata.length} configuradas</span>
          </div>
          <StructureTargetsEditor
            strata={strata}
            goals={config.goals}
            phases={config.strategy_phases}
            collectors={model.link_collectors}
            onChange={(goals) => setConfig({ ...config, goals, objetivo_total: null })}
            onPhasesChange={(strategy_phases) => setConfig({ ...config, strategy_phases })}
          />
        </div>
        )}

        {showCases && (
        <div className="mon-contract-block">
          <div className="mon-contract-block-head">
            <span>Base de barrido</span>
            <label className="mon-switch-line">
              <input
                type="checkbox"
                checked={model.cases.enabled}
                onChange={(e) => updateCases({ enabled: e.target.checked })}
              />
              <span>Usar barrido</span>
            </label>
          </div>
          <div className="mon-cases-body">
            <div className="mon-case-setup">
              <div className="mon-case-grid">
                <VariableSelect
                  label="Identificador"
                  value={model.cases.case_id_var}
                  variables={variableNames}
                  onChange={(value) => updateCases({ case_id_var: value })}
                />
                <VariableSelect
                  label="Persona o caso"
                  value={model.cases.person_label_var}
                  variables={variableNames}
                  onChange={(value) => updateCases({ person_label_var: value })}
                />
                <VariableSelect
                  label="Estado reportado"
                  value={model.cases.status_var}
                  variables={variableNames}
                  onChange={(value) => updateCases({ status_var: value })}
                />
                <label>
                  <span>Origen del barrido</span>
                  <select
                    value={model.cases.roster_source}
                    onChange={(e) => updateCases({ roster_source: e.target.value as MonitoreoOperationalCases["roster_source"] })}
                  >
                    {ROSTER_SOURCE_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>{option.label}</option>
                    ))}
                  </select>
                </label>
              </div>
              <div className="mon-case-chip-grid">
                <VariableChipSelector
                  label="Campos de contacto"
                  values={model.cases.contact_vars}
                  variables={variableNames}
                  onChange={(values) => updateCases({ contact_vars: values })}
                />
                <VariableChipSelector
                  label="Campos sensibles"
                  values={model.cases.sensitive_vars}
                  variables={variableNames}
                  onChange={(values) => updateCases({ sensitive_vars: values })}
                />
              </div>
            </div>
            <div className="mon-data-layer-grid" aria-label="Capas de datos operativos">
              {DATA_LAYER_GUIDE.map((layer) => (
                <button
                  key={layer.key}
                  type="button"
                  className={`mon-data-layer-card${model.cases.roster_source === layer.key ? " is-active" : ""}`}
                  onClick={() => updateCases({ roster_source: layer.key })}
                >
                  <span>{layer.meta}</span>
                  <strong>{layer.label}</strong>
                  <em>{layer.detail}</em>
                </button>
              ))}
            </div>
          </div>
        </div>
        )}

        {showLinks && (
        <CollectorLinksPanel
          sources={sources}
          config={config}
          setConfig={setConfig}
          onConfigPersisted={onConfigPersisted}
        />
        )}

        {showStrategies && (
        <div className="mon-contract-block">
          <div className="mon-contract-block-head">
            <span>Acciones del calendario</span>
            <button type="button" onClick={addStrategy}><Plus size={13} /> Agregar acción</button>
          </div>
          {model.strategies.length ? (
            <div className="mon-contract-list">
              {model.strategies.map((strategy, index) => (
                <div key={strategy.id || index} className="mon-contract-row mon-strategy-editor-row">
                  <label>
                    <span>Nombre</span>
                    <select
                      value={strategy.label}
                      onChange={(e) => updateStrategy(index, { label: e.target.value })}
                    >
                      <option value="">Seleccionar acción</option>
                      {withCurrentOption(strategyLabelOptions, strategy.label).map((option) => (
                        <option key={option} value={option}>{option}</option>
                      ))}
                    </select>
                  </label>
                  <label>
                    <span>Estado</span>
                    <select
                      value={strategy.status}
                      onChange={(e) => updateStrategy(index, { status: e.target.value as MonitoreoOperationalStrategy["status"] })}
                    >
                      <option value="draft">Borrador</option>
                      <option value="active">Activa</option>
                      <option value="paused">Pausada</option>
                      <option value="closed">Cerrada</option>
                    </select>
                  </label>
                  <label>
                    <span>Responsable</span>
                    <select
                      value={strategy.owner}
                      onChange={(e) => updateStrategy(index, { owner: e.target.value })}
                    >
                      <option value="">Sin asignar</option>
                      {withCurrentOption(STRATEGY_OWNER_OPTIONS, strategy.owner).map((option) => (
                        <option key={option} value={option}>{option}</option>
                      ))}
                    </select>
                  </label>
                  <label className="mon-row-span">
                    <span>Objetivo</span>
                    <select
                      value={strategy.objective}
                      onChange={(e) => updateStrategy(index, { objective: e.target.value })}
                    >
                      <option value="">Seleccionar objetivo</option>
                      {withCurrentOption(STRATEGY_OBJECTIVE_OPTIONS, strategy.objective).map((option) => (
                        <option key={option} value={option}>{option}</option>
                      ))}
                    </select>
                  </label>
                  <button
                    type="button"
                    className="mon-icon-action"
                    aria-label="Quitar acción"
                    onClick={() => setModel({ strategies: model.strategies.filter((_, i) => i !== index) })}
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <EmptyState icon={<Route size={18} />} title="Sin acciones de calendario" variant="inline" />
          )}
        </div>
        )}

        {showRules && (
        <div className="mon-contract-block mon-contract-block--wide">
          <div className="mon-contract-block-head">
            <span>Estados y resultados</span>
            <span className="mon-contract-counter">{model.events.length} resultados · {model.state_rules.length} estados</span>
          </div>
          <div className="mon-events-rules-grid">
            <div className="mon-contract-list">
              {model.events.map((event, index) => (
                <div key={event.id || index} className="mon-event-row">
                  <label>
                    <span>Evento</span>
                    <select
                      value={event.label}
                      onChange={(e) => {
                        const preset = EVENT_PRESETS.find((item) => item.label === e.target.value);
                        updateEvent(index, preset ? { ...preset } : { label: e.target.value });
                      }}
                    >
                      <option value="">Seleccionar evento</option>
                      {withCurrentOption(EVENT_PRESETS.map((item) => item.label), event.label).map((option) => (
                        <option key={option} value={option}>{prettyOperationalLabel(option)}</option>
                      ))}
                    </select>
                  </label>
                  <label>
                    <span>Modalidad</span>
                    <select
                      value={event.modality}
                      onChange={(e) => updateEvent(index, { modality: e.target.value as MonitoreoStrategyPhase["modality"] })}
                    >
                      <option value="telefono">Teléfono</option>
                      <option value="email">Correo</option>
                      <option value="whatsapp">WhatsApp</option>
                      <option value="sms">SMS</option>
                      <option value="presencial">Presencial</option>
                      <option value="mixto">Mixto</option>
                    </select>
                  </label>
                  <label>
                    <span>Resultado</span>
                    <select value={event.outcome} onChange={(e) => updateEvent(index, { outcome: e.target.value })}>
                      {outcomeOptions(model.events, [event.outcome]).map((option) => (
                        <option key={option.value} value={option.value}>{option.label}</option>
                      ))}
                    </select>
                  </label>
                  <div className="mon-boolean-cluster" aria-label={`Marcadores de ${event.label || "evento"}`}>
                    <CheckboxPill label="Intento" checked={event.counts_attempt} onChange={(checked) => updateEvent(index, { counts_attempt: checked })} />
                    <CheckboxPill label="Contacto" checked={event.counts_contact} onChange={(checked) => updateEvent(index, { counts_contact: checked })} />
                    <CheckboxPill label="Completa" checked={event.counts_complete} onChange={(checked) => updateEvent(index, { counts_complete: checked })} />
                    <CheckboxPill label="Cierra" checked={event.stop_contact} onChange={(checked) => updateEvent(index, { stop_contact: checked })} />
                  </div>
                </div>
              ))}
            </div>
            <div className="mon-contract-list">
              {model.state_rules.map((rule, index) => (
                <div key={rule.id || index} className="mon-rule-row">
                  <label>
                    <span>Regla</span>
                    <select
                      value={rule.label}
                      onChange={(e) => {
                        const preset = STATE_RULE_PRESETS.find((item) => item.label === e.target.value);
                        updateRule(index, preset ? { ...preset } : { label: e.target.value });
                      }}
                    >
                      <option value="">Seleccionar regla</option>
                      {withCurrentOption(STATE_RULE_PRESETS.map((item) => item.label), rule.label).map((option) => (
                        <option key={option} value={option}>{prettyOperationalLabel(option)}</option>
                      ))}
                    </select>
                  </label>
                  <label>
                    <span>Estado final</span>
                    <select value={rule.final_state} onChange={(e) => updateRule(index, { final_state: e.target.value })}>
                      {FINAL_STATE_OPTIONS.map((option) => (
                        <option key={option.value} value={option.value}>{option.label}</option>
                      ))}
                      {!FINAL_STATE_OPTIONS.some((option) => option.value === rule.final_state) && (
                        <option value={rule.final_state}>{rule.final_state}</option>
                      )}
                    </select>
                  </label>
                  <label>
                    <span>Prioridad</span>
                    <input
                      type="number"
                      min={1}
                      value={rule.priority}
                      onChange={(e) => updateRule(index, { priority: numberOrFallback(e.target.value, index + 1) })}
                    />
                  </label>
                  <OutcomeValuePicker
                    label="Valores resultado"
                    values={rule.outcome_values}
                    options={outcomeOptions(model.events, rule.outcome_values)}
                    onChange={(outcome_values) => updateRule(index, { outcome_values })}
                  />
                  <CheckboxPill label="Detiene contacto" checked={rule.stop_contact} onChange={(checked) => updateRule(index, { stop_contact: checked })} />
                </div>
              ))}
            </div>
          </div>
        </div>
        )}
      </div>
    </div>
  );
}

function CollectorLinksPanel({
  sources,
  config,
  setConfig,
  onConfigPersisted,
}: {
  sources: MonitoreoSource[];
  config: MonitoreoConfig;
  setConfig: (next: MonitoreoConfig) => void;
  onConfigPersisted: (next: MonitoreoState) => void;
}) {
  const [items, setItems] = useState<MonitoreoSurveyMonkeyCollector[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [loadedAt, setLoadedAt] = useState("");
  const [loadMode, setLoadMode] = useState<"local_snapshot" | "surveymonkey" | "">("");
  const sourceIds = sources
    .filter((source) => source.kind === "surveymonkey" && source.enabled)
    .map((source) => source.id);

  const configuredMap = useMemo(() => {
    const out = new Map<string, MonitoreoLinkCollector>();
    for (const item of config.operational_model.link_collectors) {
      out.set(`${item.source_id}::${item.collector_id}`, item);
    }
    return out;
  }, [config.operational_model.link_collectors]);

  const mergedItems = useMemo(() => items.map((item) => {
    const saved = configuredMap.get(`${item.source_id}::${item.collector_id}`);
    return saved ? { ...item, ...saved, configured_use: saved.operational_use } : item;
  }), [items, configuredMap]);

  const summary = useMemo(() => {
    const recipients = mergedItems.reduce((sum, item) => sum + numberOrFallback(item.recipient_summary?.total, 0), 0);
    const links = mergedItems.reduce((sum, item) => sum + numberOrFallback(item.recipient_summary?.personalized_link_count, 0), 0);
    const active = mergedItems.reduce((sum, item) => sum + numberOrFallback(item.active_response_count, 0), 0);
    return { recipients, links, active };
  }, [mergedItems]);

  async function loadCollectors(remote = false) {
    if (!sourceIds.length) {
      setItems([]);
      setLoadMode("");
      return;
    }
    setLoading(true);
    setError("");
    try {
      const out = await apiMonitoreoSurveyMonkeyCollectors(sourceIds, { remote });
      setItems(out.collectors);
      setLoadedAt(out.generated_at);
      setLoadMode(out.mode);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void loadCollectors(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sourceIds.join("|")]);

  function updateCollector(item: MonitoreoSurveyMonkeyCollector, patch: Partial<MonitoreoLinkCollector>) {
    const key = `${item.source_id}::${item.collector_id}`;
    const current = configuredMap.get(key) ?? collectorConfigFromDiscovery(item);
    const operationalUse = normalizeCollectorUse(patch.operational_use ?? current.operational_use);
    const nextItem: MonitoreoLinkCollector = {
      ...current,
      ...patch,
      operational_use: operationalUse,
      modality: patch.modality ?? (patch.operational_use ? modalityForCollectorUse(operationalUse) : current.modality),
      roster_required: patch.roster_required ?? (patch.operational_use ? operationalUse === "telefono_asistido" : current.roster_required),
    };
    const others = config.operational_model.link_collectors.filter((collector) => `${collector.source_id}::${collector.collector_id}` !== key);
    setConfig({
      ...config,
      operational_model: mergeOperationalModel({
        ...config.operational_model,
        link_collectors: [...others, nextItem],
      }),
    });
  }

  function applySuggestions() {
    const next = mergedItems.map((item) => collectorConfigFromDiscovery({
      ...item,
      operational_use: item.suggested_use,
      modality: modalityForCollectorUse(item.suggested_use),
      roster_required: item.suggested_use === "telefono_asistido",
    }));
    setConfig({
      ...config,
      operational_model: mergeOperationalModel({
        ...config.operational_model,
        link_collectors: next,
      }),
    });
  }

  async function saveCollectors() {
    setSaving(true);
    setError("");
    try {
      const payload = mergedItems.length
        ? mergedItems.map(collectorConfigFromDiscovery)
        : config.operational_model.link_collectors;
      const result = await apiMonitoreoCollectorsConfig(payload);
      onConfigPersisted(result.state);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="mon-contract-block mon-contract-block--wide mon-collector-manager">
      <div className="mon-contract-block-head">
        <span>Enlaces y envíos SurveyMonkey</span>
        <div className="mon-collector-actions">
          <button type="button" onClick={() => loadCollectors(false)} disabled={loading || !sourceIds.length}>
            {loading ? <Loader2 size={13} className="pulso-spin" /> : <RefreshCw size={13} />}
            Actualizar
          </button>
          <button type="button" onClick={() => loadCollectors(true)} disabled={loading || !sourceIds.length}>
            {loading ? <Loader2 size={13} className="pulso-spin" /> : <PlugZap size={13} />}
            Leer SurveyMonkey
          </button>
          <button type="button" onClick={applySuggestions} disabled={!mergedItems.length}>
            <CheckCircle2 size={13} />
            Clasificar
          </button>
          <button type="button" className="pulso-primary" onClick={saveCollectors} disabled={saving}>
            {saving ? <Loader2 size={13} className="pulso-spin" /> : <Save size={13} />}
            Guardar
          </button>
        </div>
      </div>

      <div className="mon-collector-summary" aria-label="Resumen de enlaces y envíos">
        <span>{mergedItems.length} enlaces/envíos</span>
        <span>{summary.active.toLocaleString("es-PE")} respuestas</span>
        <span>{summary.recipients.toLocaleString("es-PE")} destinatarios observados</span>
        <span>{summary.links.toLocaleString("es-PE")} links usados</span>
        {loadMode && <span>{loadMode === "surveymonkey" ? "SurveyMonkey" : "Datos sincronizados"}</span>}
        {loadedAt && <span>{formatDate(loadedAt)}</span>}
      </div>

      <div className="mon-collector-body">
        {error && <Alert kind="error">{error}</Alert>}

        {!sourceIds.length && (
          <div className="mon-sm-empty">Conecta una encuesta SurveyMonkey para leer enlaces, correos o links personalizados.</div>
        )}

        {loading && (
          <div className="mon-collector-loading">
            <Loader2 size={16} className="pulso-spin" />
            <span>Leyendo enlaces, envíos y conteos seguros...</span>
          </div>
        )}

        {!loading && sourceIds.length > 0 && !mergedItems.length && (
          <div className="mon-sm-empty">Sin enlaces o envíos detectados para las fuentes activas.</div>
        )}

        <div className="mon-collector-list">
          {mergedItems.map((item) => {
            const useOption = collectorUseOption(item.operational_use);
            const UseIcon = useOption.icon;
            const completeCount = countFromRecord(item.recipient_summary?.response_status_counts, ["completely_responded", "completed", "complete"]);
            return (
              <article key={`${item.source_id}-${item.collector_id}`} className={`mon-collector-card is-${item.modality}`}>
                <div className="mon-collector-title">
                  <span className="mon-collector-use-icon"><UseIcon size={14} /></span>
                  <div>
                    <strong>{collectorDisplayName(item)}</strong>
                    <em>{item.source_label || item.source_id}</em>
                  </div>
                  <span className="mon-collector-chip">{collectorTypeLabel(item.collector_type)}</span>
                </div>

                <div className="mon-collector-metrics">
                  <MetricTile label="Respuestas" value={item.active_response_count || item.response_count} />
                  <MetricTile label="Dest. obs." value={item.recipient_summary?.total ?? 0} />
                  <MetricTile label="Links usados" value={item.recipient_summary?.personalized_link_count ?? 0} />
                  <MetricTile label="Efectivas" value={completeCount} />
                </div>

                <div className="mon-collector-controls">
                  <label>
                    <span>Tipo de uso</span>
                    <select
                      value={item.operational_use}
                      onChange={(e) => updateCollector(item, { operational_use: e.target.value as MonitoreoCollectorUse })}
                    >
                      {COLLECTOR_USE_OPTIONS.map((option) => (
                        <option key={option.value} value={option.value}>{option.label}</option>
                      ))}
                    </select>
                  </label>
                  <label>
                    <span>Modalidad</span>
                    <select
                      value={item.modality}
                      onChange={(e) => updateCollector(item, { modality: e.target.value as MonitoreoStrategyPhase["modality"] })}
                    >
                      <option value="email">Correo</option>
                      <option value="telefono">Teléfono</option>
                      <option value="presencial">Presencial</option>
                      <option value="whatsapp">WhatsApp</option>
                      <option value="sms">SMS</option>
                      <option value="mixto">Mixto</option>
                    </select>
                  </label>
                  <label className="mon-switch-line mon-collector-roster">
                    <input
                      type="checkbox"
                      checked={item.roster_required}
                      onChange={(e) => updateCollector(item, { roster_required: e.target.checked })}
                    />
                    <span>Requiere barrido</span>
                  </label>
                </div>

                {(item.warnings?.length || item.recipient_summary?.truncated) && (
                  <div className="mon-collector-warnings">
                    {item.recipient_summary?.truncated && <span>Conteo de destinatarios muestreado</span>}
                    {item.warnings?.map((warning) => <span key={warning}>{warning}</span>)}
                  </div>
                )}
              </article>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function collectorConfigFromDiscovery(item: MonitoreoSurveyMonkeyCollector): MonitoreoLinkCollector {
  const operationalUse = normalizeCollectorUse(item.operational_use || item.suggested_use);
  return {
    id: item.id || `${item.source_id}::${item.collector_id}`,
    source_id: item.source_id,
    source_label: item.source_label,
    survey_id: item.survey_id,
    collector_id: item.collector_id,
    collector_name: item.collector_name,
    collector_type: item.collector_type,
    operational_use: operationalUse,
    modality: item.modality || modalityForCollectorUse(operationalUse),
    roster_required: item.roster_required ?? operationalUse === "telefono_asistido",
  };
}

function collectorUseOption(value: MonitoreoCollectorUse) {
  return COLLECTOR_USE_OPTIONS.find((option) => option.value === value) ?? COLLECTOR_USE_OPTIONS[COLLECTOR_USE_OPTIONS.length - 1];
}

function collectorTypeLabel(value: string) {
  const normalized = value.toLowerCase();
  if (normalized === "email") return "Envío por correo";
  if (normalized === "weblink" || normalized === "web_link") return "Link abierto";
  if (normalized === "sms") return "SMS";
  return value || "Enlace";
}

function collectorDisplayName(item: MonitoreoSurveyMonkeyCollector | MonitoreoLinkCollector) {
  const raw = String(item.collector_name || item.collector_id || "Enlace").trim();
  if (/^collector\s+/i.test(raw)) return raw.replace(/^collector/i, "Enlace");
  if (/^colector\s+/i.test(raw)) return raw.replace(/^colector/i, "Enlace");
  return raw;
}

function countFromRecord(record: Record<string, number> | undefined, keys: string[]) {
  if (!record) return 0;
  return keys.reduce((sum, key) => sum + numberOrFallback(record[key], 0), 0);
}

function MetricTile({ label, value, tone = "neutral" }: { label: string; value: number; tone?: "neutral" | "ready" | "warning" }) {
  return (
    <div className={`mon-collector-metric is-${tone}`}>
      <span>{label}</span>
      <strong>{value.toLocaleString("es-PE")}</strong>
    </div>
  );
}

function StructureTargetsEditor({
  strata,
  goals,
  phases,
  collectors,
  onChange,
  onPhasesChange,
}: {
  strata: OperationalStratum[];
  goals: MonitoreoGoal[];
  phases: MonitoreoStrategyPhase[];
  collectors: MonitoreoLinkCollector[];
  onChange: (next: MonitoreoGoal[]) => void;
  onPhasesChange: (next: MonitoreoStrategyPhase[]) => void;
}) {
  const total = goals.reduce((sum, goal) => sum + Math.max(0, numberOrFallback(goal.meta, 0)), 0);
  const configured = strata.filter((stratum) => goalForStratum(goals, stratum) != null).length;

  function setMeta(stratum: OperationalStratum, raw: string) {
    const filters = primaryGoalFiltersForStratum(stratum);
    if (!Object.keys(filters).length) return;
    const meta = raw === "" ? 0 : Math.max(0, Math.round(Number(raw) || 0));
    onChange(upsertGoalForFilters(goals, filters, meta));
  }

  function clearMeta(stratum: OperationalStratum) {
    const filters = primaryGoalFiltersForStratum(stratum);
    onChange(goals.filter((goal) => !goalMatchesFilters(goal, filters)));
  }

  function setStratumPhase(
    stratum: OperationalStratum,
    slot: "primary" | "secondary" | "third",
    rawModality: string,
  ) {
    const entries = phaseEntriesForStratum(stratum.title, phases);
    const slotIndex = slot === "primary" ? 0 : slot === "secondary" ? 1 : 2;
    const phaseEntry = entries[slotIndex] ?? null;
    const previousEntry = entries[slotIndex - 1] ?? null;

    if (slot !== "primary" && !rawModality) {
      if (!phaseEntry) return;
      onPhasesChange(phases.filter((_, index) => index !== phaseEntry.index));
      return;
    }
    if (!rawModality) return;

    const modality = rawModality as MonitoreoStrategyPhase["modality"];
    const nextPhases = phases.slice();
    const defaultStartWeek = slotIndex === 0
      ? 1
      : Math.max(2, (previousEntry?.phase.end_week ?? previousEntry?.phase.start_week ?? slotIndex) + 1);
    if (phaseEntry) {
      nextPhases[phaseEntry.index] = phaseWithModality(phaseEntry.phase, stratum, modality);
    } else {
      nextPhases.push(defaultPhaseForStratum(stratum, modality, { start_week: defaultStartWeek, end_week: null }));
    }
    onPhasesChange(nextPhases);
  }

  if (!strata.length) {
    return <EmptyState icon={<Target size={18} />} title="Sin cortes para asignar meta" variant="inline" />;
  }

  return (
    <div className="mon-target-editor">
      <div className="mon-target-editor-summary">
        <span>
          <strong>{configured}/{strata.length}</strong>
          <em>con meta</em>
        </span>
        <span>
          <strong>{total ? total.toLocaleString("es-PE") : "S/M"}</strong>
          <em>meta total</em>
        </span>
      </div>
      <div className="mon-target-card-list">
        {strata.map((stratum) => {
          const facts = parseStratumFacts(stratum.detail);
          const meta = goalForStratum(goals, stratum);
          const phaseEntries = phaseEntriesForStratum(stratum.title, phases);
          const primaryPhase = phaseEntries[0]?.phase ?? null;
          const secondaryPhase = phaseEntries[1]?.phase ?? null;
          const thirdPhase = phaseEntries[2]?.phase ?? null;
          const observedUse = observedCollectorUseForStratum(stratum, collectors);
          const observedModality = modalityFromObservedUse(stratum, observedUse);
          const primaryModality = primaryPhase?.modality ?? observedModality ?? inferModalityForStratum(stratum.title);
          const filters = primaryGoalFiltersForStratum(stratum);
          const filterText = Object.entries(filters)
            .map(([key, value]) => `${dimensionLabel(key.replace(/^dim_/, ""))}: ${value}`)
            .join(" · ");
          return (
            <article key={stratum.id} className={`mon-target-card${meta != null ? " is-configured" : ""}`}>
              <div className="mon-target-card-main">
                <strong>{stratum.title}</strong>
                <span>{filterText || stratum.source}</span>
              </div>
              <div className="mon-target-facts">
                {facts.universe != null && <span>Universo {facts.universe.toLocaleString("es-PE")}</span>}
                {facts.recommended != null && <span>Recom. {facts.recommended.toLocaleString("es-PE")}</span>}
                {facts.technique && <span>{facts.technique}</span>}
                <span>Observado: {observedUse?.label ?? "Sin clasificar"}</span>
                {meta == null && facts.minimum != null && (
                  <button type="button" onClick={() => setMeta(stratum, String(facts.minimum))}>
                    Min. {facts.minimum.toLocaleString("es-PE")}
                  </button>
                )}
                {meta == null && facts.recommended != null && facts.recommended !== facts.minimum && (
                  <button type="button" onClick={() => setMeta(stratum, String(facts.recommended))}>
                    Recom. {facts.recommended.toLocaleString("es-PE")}
                  </button>
                )}
              </div>
              <label className="mon-target-meta-input">
                <span>Meta</span>
                <input
                  type="number"
                  min={0}
                  value={meta ?? ""}
                  onChange={(e) => setMeta(stratum, e.target.value)}
                  placeholder="0"
                />
              </label>
              <button
                type="button"
                className="mon-icon-action"
                aria-label="Quitar meta"
                disabled={meta == null}
                onClick={() => clearMeta(stratum)}
              >
                <Trash2 size={13} />
              </button>
              <div className="mon-target-modality">
                <label>
                  <span>1er mecanismo</span>
                  <select
                    value={primaryModality}
                    onChange={(e) => setStratumPhase(stratum, "primary", e.target.value)}
                  >
                    {MODALITY_SELECT_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>{option.label}</option>
                    ))}
                  </select>
                </label>
                <label>
                  <span>2do mecanismo</span>
                  <select
                    value={secondaryPhase?.modality ?? ""}
                    onChange={(e) => setStratumPhase(stratum, "secondary", e.target.value)}
                  >
                    <option value="">Sin segundo</option>
                    {MODALITY_SELECT_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>{option.label}</option>
                    ))}
                  </select>
                </label>
                <label>
                  <span>3er mecanismo</span>
                  <select
                    value={thirdPhase?.modality ?? ""}
                    onChange={(e) => setStratumPhase(stratum, "third", e.target.value)}
                  >
                    <option value="">Sin tercero</option>
                    {MODALITY_SELECT_OPTIONS.map((option) => (
                      <option key={option.value} value={option.value}>{option.label}</option>
                    ))}
                  </select>
                </label>
              </div>
            </article>
          );
        })}
      </div>
    </div>
  );
}

function primaryGoalFiltersForStratum(stratum: OperationalStratum) {
  const entries = Object.entries(stratum.filters).filter(([, value]) => String(value ?? "").trim());
  const preferred = ["dim_segmento", "segmento", "dim_actor", "actor", "dim_servicio", "servicio", "dim_territorio", "territorio"];
  const selected = preferred
    .map((key) => entries.find(([entryKey]) => entryKey === key))
    .find(Boolean) ?? entries[0];
  if (!selected) return {};
  const [key, value] = selected;
  return { [key.startsWith("dim_") || key === "actor" ? key : `dim_${key}`]: String(value) };
}

function goalForStratum(goals: MonitoreoGoal[], stratum: OperationalStratum) {
  const filters = primaryGoalFiltersForStratum(stratum);
  return goals.find((goal) => goalMatchesFilters(goal, filters))?.meta ?? null;
}

function goalMatchesFilters(goal: MonitoreoGoal, filters: Record<string, string>) {
  const entries = Object.entries(filters).filter(([, value]) => String(value ?? "").trim());
  if (!entries.length) return false;
  return entries.every(([key, value]) => {
    const candidates = key.startsWith("dim_") ? [key, key.replace(/^dim_/, "")] : [key, `dim_${key}`];
    return candidates.some((candidate) => normalizeMatch(goal.filters[candidate]) === normalizeMatch(value));
  });
}

function upsertGoalForFilters(goals: MonitoreoGoal[], filters: Record<string, string>, meta: number) {
  const index = goals.findIndex((goal) => goalMatchesFilters(goal, filters));
  if (index >= 0) {
    return goals.map((goal, i) => i === index ? { ...goal, filters, meta } : goal);
  }
  return [...goals, { filters, meta }];
}

function parseStratumFacts(detail: string) {
  const numberFrom = (pattern: RegExp) => {
    const match = detail.match(pattern);
    return match?.[1] ? Number(match[1].replace(/[^\d]/g, "")) : null;
  };
  const textFrom = (pattern: RegExp) => {
    const match = detail.match(pattern);
    return match?.[1]?.trim().replace(/\.$/, "") ?? "";
  };
  return {
    universe: numberFrom(/universo\s*[: ]\s*(\d[\d.,]*)/i),
    minimum: numberFrom(/meta\s+m[ií]nima\s*[: ]\s*(\d[\d.,]*)/i),
    recommended: numberFrom(/recomendada\s*[: ]\s*(\d[\d.,]*)/i),
    technique: textFrom(/t[eé]cnica\s*[: ]\s*([^;]+)/i),
    control: textFrom(/control\s*[: ]\s*([^;]+)/i),
  };
}

function ModelInspector({
  mode,
  config,
  setConfig,
  variables,
  strata,
}: {
  mode: OperationalModelMode;
  config: MonitoreoConfig;
  setConfig: (next: MonitoreoConfig) => void;
  variables: MonitoreoVariable[];
  strata: OperationalStratum[];
}) {
  const names = variables.map((variable) => variable.name);
  const set = (patch: Partial<MonitoreoConfig>) => setConfig({ ...config, ...patch });
  const modeLabel = OPERATIONAL_MODEL_MODES.find((item) => item.key === mode)?.label ?? "Modelo";
  const goalTotal = config.goals.reduce((sum, goal) => sum + Math.max(0, numberOrFallback(goal.meta, 0)), 0);
  return (
    <Panel
      className="mon-fill-panel mon-model-inspector"
      eyebrow="Inspector"
      title={<span className="mon-title-icon"><SlidersHorizontal size={16} /> Variables y estado</span>}
    >
      <div className="mon-inspector-scroll">
        <div className="mon-inspector-meter">
          <span>
            <strong>{modeLabel}</strong>
            <em>Modo activo</em>
          </span>
          <span>
            <strong>{variables.length}</strong>
            <em>Variables detectadas</em>
          </span>
          <span>
            <strong>{strata.length}</strong>
            <em>Cortes visibles</em>
          </span>
        </div>

        <div className="mon-inspector-section">
          <div className="mon-inspector-section-head">
            <span>
              {mode === "estructura" && "Cortes y metas"}
              {mode === "enlaces" && "Enlaces y envíos"}
              {mode === "casos" && "Base de barrido"}
              {mode === "estrategias" && "Calendario"}
              {mode === "reglas" && "Estados válidos"}
            </span>
          </div>
          {mode === "estructura" && (
            <>
              <div className="mon-inspector-total">
                <span>Meta total</span>
                <strong>{goalTotal ? goalTotal.toLocaleString("es-PE") : "S/M"}</strong>
                <em>{config.goals.length} metas por corte</em>
              </div>
              <ChipPicker label="Variables de corte / estrato" vars={names} selected={config.control_vars} onChange={(control_vars) => set({ control_vars })} />
            </>
          )}
          {mode === "casos" && (
            <>
              <div className="mon-case-grid">
                <VarSelect label="ID" value={config.id_var} vars={names} onChange={(value) => set({ id_var: value })} />
                <VarSelect label="Contacto" value={config.contact_var} vars={names} onChange={(value) => set({ contact_var: value })} />
                <VarSelect label="Estado" value={config.status_var} vars={names} onChange={(value) => set({ status_var: value })} />
                <VarSelect label="Fecha" value={config.date_var} vars={names} onChange={(value) => set({ date_var: value })} />
              </div>
              <p className="mon-inspector-note">
                La base de barrido es opcional: telefono y presencial la usan para responsable, status, intentos y fecha; correo suele apoyarse en universo/contactos y respuesta de plataforma.
              </p>
              <ChipPicker label="Campos criticos" vars={names} selected={config.critical_vars} onChange={(critical_vars) => set({ critical_vars })} />
            </>
          )}
          {mode === "enlaces" && (
            <>
              <div className="mon-inspector-total">
                <span>Clasificados</span>
                <strong>{config.operational_model.link_collectors.length}</strong>
                <em>Enlaces/envíos guardados</em>
              </div>
              <div className="mon-token-list">
                {COLLECTOR_USE_OPTIONS.filter((option) =>
                  config.operational_model.link_collectors.some((collector) => collector.operational_use === option.value),
                ).map((option) => (
                  <button key={option.value} type="button">
                    {option.label}
                  </button>
                ))}
              </div>
            </>
          )}
          {mode === "estrategias" && (
            <div className="mon-case-grid">
              <VarSelect label="Enumerador" value={config.enumerator_var} vars={names} onChange={(value) => set({ enumerator_var: value })} />
              <VarSelect label="Fecha" value={config.date_var} vars={names} onChange={(value) => set({ date_var: value })} />
              <VarSelect label="Duración" value={config.duration_var} vars={names} onChange={(value) => set({ duration_var: value })} />
              <VarSelect label="Estado" value={config.status_var} vars={names} onChange={(value) => set({ status_var: value })} />
            </div>
          )}
          {mode === "reglas" && (
            <>
              <VarSelect label="Estado" value={config.status_var} vars={names} onChange={(value) => set({ status_var: value })} />
              <OutcomeValuePicker
                label="Estados válidos"
                values={config.valid_statuses}
                options={outcomeOptions(config.operational_model.events, config.valid_statuses)}
                onChange={(valid_statuses) => set({ valid_statuses })}
              />
              <ChipPicker label="Campos criticos" vars={names} selected={config.critical_vars} onChange={(critical_vars) => set({ critical_vars })} />
            </>
          )}
        </div>
      </div>
    </Panel>
  );
}

function VariableSelect({
  label,
  value,
  variables,
  onChange,
}: {
  label: string;
  value: string;
  variables: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label>
      <span>{label}</span>
      <select value={value} onChange={(e) => onChange(e.target.value)}>
        <option value="">Sin asignar</option>
        {variables.map((variable) => <option key={variable} value={variable}>{variable}</option>)}
      </select>
    </label>
  );
}

function VariableChipSelector({
  label,
  values,
  variables,
  onChange,
}: {
  label: string;
  values: string[];
  variables: string[];
  onChange: (values: string[]) => void;
}) {
  return <TokenVariablePicker label={label} values={values} variables={variables} onChange={onChange} />;
}

function OutcomeValuePicker({
  label,
  values,
  options,
  onChange,
}: {
  label: string;
  values: string[];
  options: Array<{ value: string; label: string }>;
  onChange: (values: string[]) => void;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const available = options.filter((option) => !values.includes(option.value));
  const filtered = available
    .filter((option) => {
      const q = normalizeMatch(query);
      if (!q) return true;
      return normalizeMatch(`${option.label} ${option.value}`).includes(q);
    })
    .slice(0, 48);
  return (
    <div className="mon-outcome-picker mon-row-span">
      <span>{label}</span>
      <Popover.Root open={open} onOpenChange={setOpen}>
        <Popover.Trigger asChild>
          <button type="button" className="mon-territorial-select-trigger">
            <strong>{available.length ? "Agregar resultado..." : "Sin resultados disponibles"}</strong>
            <ChevronDown size={14} />
          </button>
        </Popover.Trigger>
        <Popover.Portal>
          <Popover.Content className="mon-territorial-select-popover" align="start" sideOffset={6}>
            <div className="mon-territorial-select-search">
              <Search size={13} />
              <input
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Buscar valor..."
                autoFocus
              />
            </div>
            <div className="mon-territorial-select-options">
              {filtered.map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => {
                    onChange([...values, option.value]);
                    setQuery("");
                    if (available.length <= 1) setOpen(false);
                  }}
                >
                  <div>
                    <strong>{option.label}</strong>
                    <em>{option.value}</em>
                  </div>
                  <Plus size={14} />
                </button>
              ))}
              {!filtered.length ? (
                <p>{available.length ? "No hay coincidencias." : "Ya seleccionaste todos los valores disponibles."}</p>
              ) : null}
            </div>
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>
      <div className="mon-token-list">
        {values.length ? values.map((value) => (
          <button
            key={value}
            type="button"
            onClick={() => onChange(values.filter((item) => item !== value))}
            title="Quitar resultado"
          >
            {options.find((option) => option.value === value)?.label ?? outcomeLabel(value)}
            <XCircle size={12} />
          </button>
        )) : (
          <span className="mon-muted-chip">Sin resultados seleccionados</span>
        )}
      </div>
    </div>
  );
}

function TokenVariablePicker({
  label,
  values,
  variables,
  onChange,
}: {
  label: string;
  values: string[];
  variables: string[];
  onChange: (values: string[]) => void;
}) {
  const available = variables.filter((variable) => !values.includes(variable));
  return (
    <div className="mon-token-picker">
      <span>{label}</span>
      <select
        value=""
        onChange={(e) => {
          const value = e.target.value;
          if (value) onChange([...values, value]);
        }}
      >
        <option value="">{available.length ? "Agregar variable..." : "Sin variables disponibles"}</option>
        {available.map((variable) => <option key={variable} value={variable}>{variable}</option>)}
      </select>
      <div className="mon-token-list">
        {values.length ? values.map((variable) => (
          <button
            key={variable}
            type="button"
            onClick={() => onChange(values.filter((item) => item !== variable))}
            title="Quitar variable"
          >
            {variable}
            <XCircle size={12} />
          </button>
        )) : (
          <span className="mon-muted-chip">Sin variables seleccionadas</span>
        )}
      </div>
    </div>
  );
}

function CheckboxPill({
  label,
  checked,
  onChange,
}: {
  label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}) {
  return (
    <label className={`mon-checkbox-pill${checked ? " is-active" : ""}`}>
      <input type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)} />
      <span>{label}</span>
    </label>
  );
}

function ModelStep({ icon, label, value }: { icon: ReactNode; label: string; value: string }) {
  return (
    <div className="mon-model-step">
      <span>{icon}</span>
      <div>
        <strong>{label}</strong>
        <em>{value}</em>
      </div>
    </div>
  );
}

function StrategyPlanner({
  config,
  setConfig,
  strata,
  variables,
}: {
  config: MonitoreoConfig;
  setConfig: (next: MonitoreoConfig) => void;
  strata: OperationalStratum[];
  variables: MonitoreoVariable[];
}) {
  const phases = config.strategy_phases;
  const variableNames = variables.map((variable) => variable.name);
  const stratumOptions = Array.from(new Set([
    ...strata.map((item) => item.title),
    ...phases.map((phase) => phase.stratum).filter(Boolean),
  ]));

  function setPhases(strategy_phases: MonitoreoStrategyPhase[]) {
    setConfig({ ...config, strategy_phases });
  }

  function updatePhase(index: number, patch: Partial<MonitoreoStrategyPhase>) {
    setPhases(phases.map((phase, i) => i === index ? { ...phase, ...patch } : phase));
  }

  function addPhase() {
    const id = `fase-${Date.now()}-${Math.round(Math.random() * 1000)}`;
    setPhases([
      ...phases,
      {
        ...DEFAULT_STRATEGY_PHASE,
        id,
        stratum: stratumOptions[0] ?? "",
        target_rule: DEFAULT_SCOPE_BY_MODALITY[DEFAULT_STRATEGY_PHASE.modality],
        kpi_focus: KPI_FOCUS_OPTIONS_BY_MODALITY[DEFAULT_STRATEGY_PHASE.modality].slice(0, 3),
      },
    ]);
  }

  return (
    <div className="mon-model-block mon-strategy-block">
      <div className="mon-model-block-head">
        <span>Calendario de mecanismos</span>
        <button type="button" onClick={addPhase}><Plus size={13} /> Agregar mecanismo</button>
      </div>
      {phases.length ? (
        <div className="mon-strategy-list">
          {phases.map((phase, index) => (
            <div key={phase.id || index} className="mon-strategy-row">
              <label>
                <span>Corte</span>
                <select value={phase.stratum} onChange={(e) => updatePhase(index, { stratum: e.target.value })}>
                  <option value="">Sin corte</option>
                  {stratumOptions.map((option) => <option key={option} value={option}>{option}</option>)}
                </select>
              </label>
              <label>
                <span>Mecanismo</span>
                <select
                  value={phase.modality}
                  onChange={(e) => {
                    const modality = e.target.value as MonitoreoStrategyPhase["modality"];
                    updatePhase(index, {
                      modality,
                      target_rule: DEFAULT_SCOPE_BY_MODALITY[modality],
                      kpi_focus: KPI_FOCUS_OPTIONS_BY_MODALITY[modality].slice(0, 3),
                      kpi_modules: DEFAULT_KPI_MODULES_BY_MODALITY[modality],
                    });
                  }}
                >
                  <option value="telefono">Teléfono</option>
                  <option value="email">Correo</option>
                  <option value="whatsapp">WhatsApp</option>
                  <option value="sms">SMS</option>
                  <option value="presencial">Presencial</option>
                  <option value="mixto">Mixto</option>
                </select>
              </label>
              <label>
                <span>Inicio</span>
                <input
                  type="number"
                  min={1}
                  value={phase.start_week ?? ""}
                  onChange={(e) => updatePhase(index, { start_week: numberOrNull(e.target.value) })}
                />
              </label>
              <label>
                <span>Fin</span>
                <input
                  type="number"
                  min={1}
                  value={phase.end_week ?? ""}
                  onChange={(e) => updatePhase(index, { end_week: numberOrNull(e.target.value) })}
                />
              </label>
              <div className="mon-phase-choice-grid">
                <ChoicePillGroup
                  label="Alcance"
                  options={[
                    ...scopeOptionsForModality(phase.modality).map((option) => ({ value: option.value, label: option.label })),
                    ...(phase.target_rule && !scopeOptionsForModality(phase.modality).some((option) => option.value === phase.target_rule)
                      ? [{ value: phase.target_rule, label: scopeLabel(phase.target_rule, phase.modality) }]
                      : []),
                  ]}
                  selected={phase.target_rule || DEFAULT_SCOPE_BY_MODALITY[phase.modality]}
                  onChange={(target_rule) => updatePhase(index, { target_rule: String(target_rule) })}
                />
                <ChoicePillGroup
                  label="Lecturas de avance"
                  options={focusOptionsForModality(phase.modality, phase.kpi_focus).map((value) => ({ value, label: kpiFocusLabel(value) }))}
                  selected={phase.kpi_focus}
                  multiple
                  onChange={(kpi_focus) => updatePhase(index, { kpi_focus: Array.isArray(kpi_focus) ? kpi_focus : [String(kpi_focus)] })}
                />
              </div>
              <PhaseKpiConfigurator
                phase={phase}
                config={config}
                variableNames={variableNames}
                onChange={(patch) => updatePhase(index, patch)}
              />
              <div className="mon-strategy-summary">
                <CalendarRange size={13} />
                <span>{phaseWeekLabel(phase)}</span>
              </div>
              <button
                type="button"
                className="mon-icon-action"
                aria-label="Quitar mecanismo"
                onClick={() => setPhases(phases.filter((_, i) => i !== index))}
              >
                <Trash2 size={13} />
              </button>
            </div>
          ))}
        </div>
      ) : (
        <div className="mon-strategy-empty-stack">
          <EmptyState icon={<Route size={18} />} title="Sin calendario configurado" variant="inline" />
          <div className="mon-modality-guide">
            <strong>Capas según modalidad</strong>
            <span>
              Teléfono y presencial pueden sumar una base de barrido local; correo, SMS y WhatsApp suelen partir de universo/contactos y respuesta de plataforma.
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

function ChoicePillGroup({
  label,
  options,
  selected,
  multiple = false,
  onChange,
}: {
  label: string;
  options: Array<{ value: string; label: string }>;
  selected: string | string[];
  multiple?: boolean;
  onChange: (value: string | string[]) => void;
}) {
  const selectedValues = Array.isArray(selected) ? selected : [selected].filter(Boolean);
  return (
    <div className="mon-choice-group">
      <span>{label}</span>
      <div className="mon-choice-list">
        {options.map((option) => {
          const active = selectedValues.includes(option.value);
          return (
            <button
              key={option.value}
              type="button"
              className={active ? "is-active" : ""}
              onClick={() => {
                if (multiple) {
                  onChange(toggleValue(selectedValues, option.value));
                } else {
                  onChange(option.value);
                }
              }}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function PhaseKpiConfigurator({
  phase,
  config,
  variableNames,
  onChange,
}: {
  phase: MonitoreoStrategyPhase;
  config: MonitoreoConfig;
  variableNames: string[];
  onChange: (patch: Partial<MonitoreoStrategyPhase>) => void;
}) {
  const suggested = new Set(DEFAULT_KPI_MODULES_BY_MODALITY[phase.modality]);
  return (
    <div className="mon-strategy-kpi-config">
      <div className="mon-strategy-config-section">
        <span>KPIs visibles</span>
        <div className="mon-kpi-module-grid">
          {KPI_MODULES.map((item) => {
            const active = phase.kpi_modules.includes(item.key);
            const recommended = suggested.has(item.key);
            return (
              <button
                key={item.key}
                type="button"
                className={`${active ? "is-active" : ""}${recommended ? " is-recommended" : ""}`}
                onClick={() => onChange({ kpi_modules: toggleValue(phase.kpi_modules, item.key) })}
              >
                {item.label}
              </button>
            );
          })}
        </div>
      </div>

      <TokenVariablePicker
        label="Desglose dentro del corte"
        values={phase.breakdown_vars}
        variables={variableNames}
        onChange={(breakdown_vars) => onChange({ breakdown_vars })}
      />

      <div className="mon-phase-var-grid">
        <label>
          <span>Variable de intentos</span>
          <select value={phase.attempts_var} onChange={(e) => onChange({ attempts_var: e.target.value })}>
            <option value="">Sin asignar</option>
            {variableNames.map((variable) => <option key={variable} value={variable}>{variable}</option>)}
          </select>
        </label>
        <label>
          <span>Resultado / efectividad</span>
          <select value={phase.outcome_var} onChange={(e) => onChange({ outcome_var: e.target.value })}>
            <option value="">Sin asignar</option>
            {variableNames.map((variable) => <option key={variable} value={variable}>{variable}</option>)}
          </select>
        </label>
      </div>

      <div className="mon-modality-hint">
        <Route size={13} />
        <span>{modalityDataNeed(phase.modality)}</span>
      </div>

      <div className="mon-strategy-output">
        <SlidersHorizontal size={13} />
        <span>{phaseOutputSummary(phase, config)}</span>
      </div>
    </div>
  );
}

type InternalExplorerEntryKey = "casos" | "actores" | "fuentes" | "responsables" | "fechas" | "alertas";

type InternalExplorerInventory = {
  universe: number;
  sourceRows: number;
  actorCount: number;
  traceableCases: number;
  missingKeyCases: number;
  pendingCases: number;
  responseSources: number;
  barridoSources: number;
  reportSources: number;
  validDateCount: number;
  undatedCases: number;
  collectorCount: number;
  unassignedCollectorCases: number;
  issueCount: number;
  duplicateCases: number;
  syncedLabel: string;
  sourcePills: Array<{ label: string; value: string; tone: "base" | "ready" | "warning" }>;
};

type InternalExplorerEntry = {
  key: InternalExplorerEntryKey;
  label: string;
  eyebrow: string;
  hint: string;
  count: string;
  icon: typeof BarChart3;
  tone: "base" | "ready" | "warning" | "effective" | "partial";
};

function ConsultasView({
  reports,
  sources,
  config,
  nRows,
  syncedAt,
  openIntent,
  caseReconciliationBusyId = "",
  onCaseReconciliationDecision,
}: {
  reports: MonitoreoAcreditacionReports | null;
  sources: MonitoreoSource[];
  config: MonitoreoConfig;
  nRows: number;
  syncedAt: string;
  openIntent: ExplorerOpenIntent | null;
  caseReconciliationBusyId?: string;
  onCaseReconciliationDecision?: (payload: {
    response_id: string;
    action: "keep_excluded" | "include_with_caveat";
    candidate_id?: string;
    note?: string;
  }) => void;
}) {
  const model = useMemo(() => normalizeInternalQueries(reports?.internal_queries), [reports?.internal_queries]);
  const [filters, setFilters] = useState<InternalQueryFilters>({ ...EMPTY_INTERNAL_QUERY_FILTERS });
  const [selectedCaseId, setSelectedCaseId] = useState("");
  const options = useMemo(() => buildAdaptiveInternalQueryOptions(model.cases, filters), [filters, model.cases]);
  const inventory = useMemo(
    () => buildInternalExplorerInventory(model, reports, sources, nRows, syncedAt),
    [model, reports, sources, nRows, syncedAt],
  );
  const collectorLabels = useMemo(() => buildInternalCollectorLabelMap(model.cases), [model.cases]);
  const sourceLabels = useMemo(() => buildInternalSourceLabelMap(sources), [sources]);
  const filteredCases = useMemo(() => filterInternalQueryCases(model.cases, filters), [filters, model.cases]);
  const stateScopeCases = useMemo(() => filterInternalQueryCases(model.cases, { ...filters, state: "" }), [filters, model.cases]);
  const stateSummary = useMemo(() => summarizeInternalCases(stateScopeCases), [stateScopeCases]);
  const summary = useMemo(() => summarizeInternalCases(filteredCases), [filteredCases]);
  const allSummary = useMemo(() => summarizeInternalCases(model.cases), [model.cases]);
  const pendingRiskCases = useMemo(
    () => internalPendingRiskCases(model.cases, filters.actor),
    [filters.actor, model.cases],
  );
  const selectedCase = filteredCases.find((item) => internalCaseIdentity(item) === selectedCaseId)
    ?? filteredCases[0]
    ?? null;
  const activeFilters = internalQueryHasFilters(filters);
  const generatedAt = reports ? formatDate(reports.generated_at) : inventory.syncedLabel;

  useEffect(() => {
    if (!openIntent) return;
    setFilters({ ...EMPTY_INTERNAL_QUERY_FILTERS, ...openIntent.filters });
    setSelectedCaseId(openIntent.selectedCaseId ?? "");
  }, [openIntent]);

  const patchFilters = (patch: Partial<InternalQueryFilters>) => {
    setFilters((current) => {
      const next = { ...current, ...patch };
      if (Object.prototype.hasOwnProperty.call(patch, "channel") && patch.channel !== current.channel) {
        next.collector = "";
      }
      return next;
    });
    setSelectedCaseId("");
  };
  const clearFilters = () => {
    setFilters({ ...EMPTY_INTERNAL_QUERY_FILTERS });
    setSelectedCaseId("");
  };

  const selectCase = (item: MonitoreoInternalQueryCase) => setSelectedCaseId(internalCaseIdentity(item));

  return (
    <div className="mon-stage mon-stage--consultas">
      <InternalExplorerStatusStrip inventory={inventory} generatedAt={generatedAt} />

      <section className="mon-case-explorer" aria-label="Explorador de casos del monitoreo">
        <InternalCaseExplorerToolbar
          summary={summary}
          allSummary={allSummary}
          activeFilters={activeFilters}
          filters={filters}
          options={options}
          collectorLabels={collectorLabels}
          sourceLabels={sourceLabels}
          onFilter={patchFilters}
          onClear={clearFilters}
        />
        <InternalPendingRiskStrip
          cases={pendingRiskCases}
          activeActor={filters.actor}
          onReview={(actor) => patchFilters({ actor, state: "reviewable", search: "" })}
        />
        <div className="mon-case-explorer-body">
          <InternalCasesWorkspace
            cases={filteredCases}
            selectedCase={selectedCase}
            onCaseSelect={selectCase}
            sources={sources}
            collectors={config.operational_model.link_collectors}
            stateSummary={stateSummary}
            activeState={filters.state}
            onStateFilter={(state) => patchFilters({ state })}
            title="Casos del corte"
            emptyTitle="Sin casos para mostrar"
            emptyHint="Ajusta la búsqueda o limpia filtros para volver al corte completo."
            caseReconciliationBusyId={caseReconciliationBusyId}
            onCaseReconciliationDecision={onCaseReconciliationDecision}
          />
        </div>
      </section>
    </div>
  );
}

function InternalPendingRiskStrip({
  cases,
  activeActor,
  onReview,
}: {
  cases: MonitoreoInternalQueryCase[];
  activeActor: string;
  onReview: (actor: string) => void;
}) {
  if (!cases.length) return null;
  const actorCounts = cases.reduce<Map<string, number>>((acc, item) => {
    const actor = item.actor || "Sin actor";
    acc.set(actor, (acc.get(actor) ?? 0) + 1);
    return acc;
  }, new Map());
  const actorEntries = Array.from(actorCounts.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "es"));
  const targetActor = activeActor && actorCounts.has(activeActor) ? activeActor : actorEntries[0]?.[0] ?? "";
  const exactCount = cases.reduce((acc, item) => acc + internalPendingEvidenceCandidates(item).filter((candidate) => assistedCandidateEvidenceLevel(candidate) === "exact").length, 0);
  const possibleCount = cases.reduce((acc, item) => acc + internalPendingEvidenceCandidates(item).filter((candidate) => assistedCandidateEvidenceLevel(candidate) === "possible").length, 0);
  return (
    <section className="mon-pending-risk-strip" aria-label="Pendientes con posible respuesta no reconciliada">
      <span><AlertTriangle size={15} /></span>
      <div>
        <strong>{formatCaseLabel(cases.length)} revisables pueden afectar la lista de no respuesta</strong>
        <p>
          Hay respuestas excluidas o sin llave con correo/código compatible con personas todavía pendientes.
          No cuentan como efectivas hasta decidirlas, pero conviene revisarlas antes de enviar faltantes.
        </p>
      </div>
      <ul>
        {actorEntries.slice(0, 3).map(([actor, count]) => (
          <li key={actor}><b>{actor}</b><em>{formatMetric(count)}</em></li>
        ))}
      </ul>
      <small>{formatMetric(exactCount)} exactas · {formatMetric(possibleCount)} similares</small>
      <button type="button" onClick={() => targetActor && onReview(targetActor)} disabled={!targetActor}>
        Revisar {targetActor || "casos"}
      </button>
    </section>
  );
}

function buildAdaptiveInternalQueryOptions(cases: MonitoreoInternalQueryCase[], filters: InternalQueryFilters) {
  const optionsFor = (patch: Partial<InternalQueryFilters>) => internalQueryOptions(filterInternalQueryCases(cases, { ...filters, ...patch }));
  return {
    actors: optionsFor({ actor: "", collector: "" }).actors,
    dates: optionsFor({ date: "", collector: "" }).dates,
    channels: optionsFor({ channel: "", collector: "" }).channels,
    collectors: optionsFor({ collector: "" }).collectors,
    sources: optionsFor({ source: "", collector: "" }).sources,
    states: optionsFor({ state: "", collector: "" }).states,
  };
}

